INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1727', 'Cable Standing Reverse Grip One Arm Overhead Tricep Extension', 'upper arms', 'triceps', '["shoulders"]', 'cable', 'strength', NULL, '["Stand facing away from the cable machine with your feet shoulder-width apart.","Hold the cable handle with an underhand grip and extend your arm overhead, keeping your elbow close to your head.","Keep your upper arm stationary and slowly lower the cable handle behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन से दूर की ओर मुंह करके खड़े हो जाएं।","केबल के हैंडल को अंडरहैंड ग्रिप से पकड़ें और अपनी कोहनी को अपने सिर के पास रखते हुए अपने हाथ को ऊपर की ओर फैलाएं।","अपनी ऊपरी भुजा को स्थिर रखें और अपनी कोहनी को मोड़कर धीरे-धीरे केबल के हैंडल को अपने सिर के पीछे नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपना हाथ वापस प्रारंभिक स्थिति में फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0234', 'Cable Standing Row (V-Bar)', 'back', 'upper back', '["biceps","shoulders"]', 'cable', 'strength', NULL, '["Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar attachment with an overhand grip, palms facing down.","Keep your back straight and your core engaged.","Pull the v-bar towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","वी-बार अटैचमेंट को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ नीचे की ओर हों।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, वी-बार को अपने शरीर की ओर खींचें।","गति के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0235', 'Cable Standing Shoulder External Rotation', 'shoulders', 'delts', '["rotator cuff","trapezius"]', 'cable', 'strength', NULL, '["Stand with your feet shoulder-width apart and your knees slightly bent.","Hold the cable handle with your arm extended in front of you, parallel to the ground.","Keep your elbow slightly bent and your shoulder blades pulled back.","Slowly rotate your arm outward, away from your body, while keeping your elbow in the same position.","Pause for a moment at the end of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और आपके घुटने थोड़े मुड़े हुए हों।","अपने हाथ को जमीन के समानांतर अपने सामने फैलाकर केबल के हैंडल को पकड़ें।","अपनी कोहनी को थोड़ा मोड़कर रखें और अपने कंधे के ब्लेड को पीछे की ओर खींचें।","अपनी कोहनी को उसी स्थिति में रखते हुए धीरे-धीरे अपने हाथ को अपने शरीर से दूर बाहर की ओर घुमाएं।","आंदोलन के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0236', 'Cable Standing Twist Row (V-Bar)', 'back', 'upper back', '["biceps","shoulders"]', 'cable', 'strength', NULL, '["Attach a v-bar attachment to a cable machine at chest height.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down.","Take a step back to create tension in the cable.","Keep your back straight and core engaged throughout the exercise.","Pull the v-bar towards your torso by retracting your shoulder blades and bending your elbows.","As you pull, twist your torso to one side, squeezing your shoulder blades together.","Pause for a moment at the top of the movement, feeling the contraction in your upper back.","Slowly release the tension and return to the starting position, untwisting your torso.","Repeat the movement for the desired number of repetitions, alternating the twisting direction with each rep."]', '["छाती की ऊंचाई पर एक केबल मशीन में वी-बार अटैचमेंट संलग्न करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","वी-बार को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ नीचे की ओर हों।","केबल में तनाव पैदा करने के लिए एक कदम पीछे हटें।","पूरे अभ्यास के दौरान अपनी पीठ सीधी रखें और मुख्य भाग को व्यस्त रखें।","अपने कंधे के ब्लेड को पीछे खींचकर और अपनी कोहनियों को मोड़कर वी-बार को अपने धड़ की ओर खींचें।","जैसे ही आप खींचते हैं, अपने धड़ को एक तरफ मोड़ें, अपने कंधे के ब्लेड को एक साथ निचोड़ें।","अपनी ऊपरी पीठ में संकुचन महसूस करते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","धीरे-धीरे तनाव छोड़ें और अपने धड़ को खोलते हुए प्रारंभिक स्थिति में लौट आएं।","प्रत्येक प्रतिनिधि के साथ घुमाव की दिशा को बदलते हुए, दोहराव की वांछित संख्या के लिए आंदोलन को दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1269', 'Cable Standing Up Straight Crossovers', 'chest', 'pectorals', '["deltoids","triceps"]', 'cable', 'strength', NULL, '["Stand in the middle of a cable machine with your feet shoulder-width apart.","Hold the handles of the cables with your palms facing down and your arms extended straight out to the sides.","Keeping your arms straight, bring your hands together in front of your body, crossing them over each other.","Pause for a moment, then slowly return to the starting position, keeping your arms extended.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन के बीच में खड़े हो जाएं।","अपनी हथेलियों को नीचे की ओर रखते हुए और अपनी बाहों को बगल की ओर सीधा फैलाकर केबल के हैंडल को पकड़ें।","अपनी भुजाओं को सीधा रखते हुए, अपने हाथों को अपने शरीर के सामने एक साथ लाएँ, उन्हें एक-दूसरे के ऊपर से पार करते हुए।","एक पल के लिए रुकें, फिर अपनी बाहों को फैलाए रखते हुए धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0238', 'Cable Straight Arm Pulldown', 'back', 'lats', '["shoulders","biceps"]', 'cable', 'strength', NULL, '["Attach a straight bar to the high pulley of a cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, keeping your arms straight and your palms facing down.","Engage your lats and pull the bar down towards your thighs, keeping your arms straight throughout the movement.","Pause for a moment at the bottom, then slowly return the bar to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन की ऊंची पुली पर एक सीधी पट्टी जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","अपनी बाहों को सीधा रखते हुए और अपनी हथेलियों को नीचे की ओर रखते हुए, बार को ओवरहैंड ग्रिप से पकड़ें।","अपनी लेट्स को संलग्न करें और बार को अपनी जांघों की ओर नीचे खींचें, अपनी भुजाओं को पूरे आंदोलन के दौरान सीधा रखें।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे बार को शुरुआती स्थिति में लौटा दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0237', 'Cable Straight Arm Pulldown (With Rope)', 'back', 'lats', '["biceps","forearms"]', 'cable', 'strength', NULL, '["Attach a rope to the cable machine at the highest setting.","Stand facing the machine with your feet shoulder-width apart.","Grasp the rope with both hands, palms facing down.","Extend your arms fully in front of you, keeping your elbows slightly bent.","Engage your lats and slowly pull the rope down towards your thighs, keeping your arms straight.","Pause for a moment at the bottom, then slowly release the tension and return to the starting position.","Repeat for the desired number of repetitions."]', '["उच्चतम सेटिंग पर केबल मशीन में एक रस्सी जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","रस्सी को दोनों हाथों से पकड़ें, हथेलियाँ नीचे की ओर हों।","अपनी कोहनियों को थोड़ा मुड़ा हुआ रखते हुए, अपनी भुजाओं को अपने सामने पूरी तरह फैलाएँ।","अपनी लटें संलग्न करें और अपनी भुजाओं को सीधा रखते हुए धीरे-धीरे रस्सी को अपनी जाँघों की ओर खींचें।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे तनाव छोड़ें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0239', 'Cable Straight Back Seated Row', 'back', 'upper back', '["biceps","forearms","shoulders"]', 'cable', 'strength', NULL, '["Sit on the cable row machine with your feet flat on the footrests and your knees slightly bent.","Grasp the cable handles with an overhand grip, palms facing down.","Keep your back straight and lean slightly forward from the hips.","Pull the cable handles towards your body, squeezing your shoulder blades together.","Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.","Repeat for the desired number of repetitions."]', '["केबल रो मशीन पर अपने पैरों को फ़ुटरेस्ट पर सपाट करके और अपने घुटनों को थोड़ा मोड़कर बैठें।","केबल के हैंडल को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ नीचे की ओर हों।","अपनी पीठ सीधी रखें और कूल्हों से थोड़ा आगे की ओर झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, केबल के हैंडल को अपने शरीर की ओर खींचें।","गति के चरम पर एक पल के लिए रुकें, फिर धीरे-धीरे हैंडल को प्रारंभिक स्थिति में वापस छोड़ दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0240', 'Cable Supine Reverse Fly', 'shoulders', 'delts', '["trapezius","rhomboids"]', 'cable', 'strength', NULL, '["Attach a D-handle to a low pulley cable machine and lie face down on a flat bench.","Grasp the D-handle with each hand, palms facing down, and extend your arms straight out in front of you.","Keeping your arms straight, raise them out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक लो पुली केबल मशीन में डी-हैंडल लगाएं और एक सपाट बेंच पर मुंह करके लेट जाएं।","प्रत्येक हाथ से डी-हैंडल को पकड़ें, हथेलियाँ नीचे की ओर हों, और अपनी भुजाओं को अपने सामने सीधा फैलाएँ।","अपनी भुजाओं को सीधा रखते हुए, उन्हें बगल की ओर तब तक उठाएँ जब तक कि वे फर्श के समानांतर न हो जाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2464', 'Cable Thibaudeau Kayak Row', 'back', 'lats', '["biceps","rhomboids","rear deltoids"]', 'cable', 'strength', NULL, '["Attach a cable handle to a low pulley and sit facing the machine with your feet flat on the floor.","Grasp the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow.","Lean forward from your hips, keeping your back straight and your abs engaged.","Pull the handle towards your torso by retracting your shoulder blade and bending your elbow, keeping your arm close to your body.","Squeeze your back muscles at the top of the movement, then slowly return to the starting position.","Repeat for the desired number of repetitions, then switch sides and perform with your left arm."]', '["एक केबल हैंडल को निचली पुली से जोड़ें और अपने पैरों को फर्श पर सपाट करके मशीन की ओर मुंह करके बैठें।","अपने दाहिने हाथ से हैंडल को पकड़ें और अपनी कोहनी को थोड़ा मोड़ते हुए अपने हाथ को पूरी तरह फैलाएँ।","अपने कूल्हों से आगे की ओर झुकें, अपनी पीठ सीधी रखें और अपने पेट को व्यस्त रखें।","अपने कंधे के ब्लेड को पीछे खींचकर और अपनी कोहनी को मोड़कर, अपने हाथ को अपने शरीर के करीब रखते हुए, हैंडल को अपने धड़ की ओर खींचें।","आंदोलन के शीर्ष पर अपनी पीठ की मांसपेशियों को निचोड़ें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें और अपने बाएं हाथ से प्रदर्शन करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0241', 'Cable Triceps Pushdown (V-Bar)', 'upper arms', 'triceps', '["forearms"]', 'cable', 'strength', NULL, '["Attach a v-bar attachment to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.","Pause for a moment at the bottom of the movement, squeezing your triceps.","Inhale as you slowly return the v-bar to the starting position, maintaining control.","Repeat for the desired number of repetitions."]', '["उच्चतम सेटिंग पर केबल मशीन में वी-बार अटैचमेंट संलग्न करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","वी-बार को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ नीचे की ओर हों और आपके हाथ कंधे की चौड़ाई से अलग हों।","पूरे अभ्यास के दौरान अपनी कोहनियों को अपनी भुजाओं के पास और अपनी ऊपरी भुजाओं को स्थिर रखें।","अपने ट्राइसेप्स को संलग्न करें और वी-बार को नीचे धकेलते हुए सांस छोड़ें जब तक कि आपकी भुजाएं पूरी तरह से विस्तारित न हो जाएं।","अपने ट्राइसेप्स को निचोड़ते हुए, आंदोलन के निचले भाग में एक पल के लिए रुकें।","श्वास लेते हुए आप नियंत्रण बनाए रखते हुए धीरे-धीरे वी-बार को प्रारंभिक स्थिति में लौटाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2405', 'Cable Triceps Pushdown (V-Bar) (With Arm Blaster)', 'upper arms', 'triceps', '["forearms"]', 'cable', 'strength', NULL, '["Attach a v-bar attachment to the cable machine at the highest setting.","Stand facing the cable machine with your feet shoulder-width apart.","Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.","Keep your elbows close to your sides and your upper arms stationary throughout the exercise.","Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.","Pause for a moment at the bottom of the movement, squeezing your triceps.","Inhale as you slowly return the v-bar to the starting position, maintaining control.","Repeat for the desired number of repetitions."]', '["उच्चतम सेटिंग पर केबल मशीन में वी-बार अटैचमेंट संलग्न करें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए केबल मशीन की ओर मुंह करके खड़े हो जाएं।","वी-बार को ओवरहैंड ग्रिप से पकड़ें, हथेलियाँ नीचे की ओर हों और आपके हाथ कंधे की चौड़ाई से अलग हों।","पूरे अभ्यास के दौरान अपनी कोहनियों को अपनी भुजाओं के पास और अपनी ऊपरी भुजाओं को स्थिर रखें।","अपने ट्राइसेप्स को संलग्न करें और वी-बार को नीचे धकेलते हुए सांस छोड़ें जब तक कि आपकी भुजाएं पूरी तरह से विस्तारित न हो जाएं।","अपने ट्राइसेप्स को निचोड़ते हुए, आंदोलन के निचले भाग में एक पल के लिए रुकें।","श्वास लेते हुए आप नियंत्रण बनाए रखते हुए धीरे-धीरे वी-बार को प्रारंभिक स्थिति में लौटाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0242', 'Cable Tuck Reverse Crunch', 'waist', 'abs', '["hip flexors"]', 'cable', 'strength', NULL, '["Attach a cable to a low pulley and lie down on a mat facing up.","Hold the cable with both hands and extend your arms straight up above your chest.","Bend your knees and lift your legs up, bringing your knees towards your chest.","At the same time, curl your pelvis up towards your chest, lifting your hips off the ground.","Pause for a moment at the top, then slowly lower your legs and hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक केबल को निचली पुली से जोड़ें और एक चटाई पर ऊपर की ओर मुंह करके लेट जाएं।","केबल को दोनों हाथों से पकड़ें और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपने घुटनों को मोड़ें और अपने पैरों को ऊपर उठाएं, अपने घुटनों को अपनी छाती की ओर लाएं।","साथ ही, अपने कूल्हों को ज़मीन से ऊपर उठाते हुए, अपने श्रोणि को अपनी छाती की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों और कूल्हों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0243', 'Cable Twist', 'waist', 'abs', '["obliques"]', 'cable', 'strength', NULL, '["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.","Engage your core and twist your torso to the right, pulling the cable across your body.","Pause for a moment at the end of the movement, feeling the contraction in your abs and obliques.","Slowly return to the starting position, resisting the cable''s pull.","Repeat the movement to the left side.","Continue alternating sides for the desired number of repetitions."]', '["केबल मशीन की ओर मुंह करके अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं।","केबल के हैंडल को दोनों हाथों से अपनी छाती के सामने पकड़ें, अपनी बाहों को थोड़ा झुकाकर रखें।","अपने कोर को संलग्न करें और अपने धड़ को दाईं ओर मोड़ें, केबल को अपने शरीर पर खींचें।","आंदोलन के अंत में एक पल के लिए रुकें, अपने पेट और तिरछेपन में संकुचन महसूस करें।","केबल के खिंचाव का विरोध करते हुए, धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","इस क्रिया को बायीं ओर दोहराएँ।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0862', 'Cable Twist (Up-Down)', 'waist', 'abs', '["obliques","lower back"]', 'cable', 'strength', NULL, '["Stand with your feet shoulder-width apart, facing the cable machine.","Hold the cable handle with both hands in front of your chest, keeping your arms slightly bent.","Engage your core and slowly rotate your torso to one side, keeping your hips and legs stable.","Pause for a moment at the end of the rotation, then slowly return to the starting position.","Repeat the rotation to the opposite side.","Continue alternating sides for the desired number of repetitions."]', '["केबल मशीन की ओर मुंह करके अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं।","केबल के हैंडल को दोनों हाथों से अपनी छाती के सामने पकड़ें, अपनी बाहों को थोड़ा झुकाकर रखें।","अपने कोर को संलग्न करें और अपने कूल्हों और पैरों को स्थिर रखते हुए धीरे-धीरे अपने धड़ को एक तरफ घुमाएं।","घूर्णन के अंत में एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","घूर्णन को विपरीत दिशा में दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0244', 'Cable Twisting Pull', 'back', 'lats', '["shoulders","biceps"]', 'cable', 'strength', NULL, '["Attach a cable handle to a low pulley and stand facing the machine.","Grasp the handle with your left hand and step away from the machine, extending your arm fully.","Position your feet shoulder-width apart, with your knees slightly bent.","Keep your back straight and your core engaged throughout the exercise.","Pull the handle towards your body, rotating your torso to the right as you do so.","Squeeze your back muscles at the end of the movement.","Slowly return to the starting position, keeping tension on the cable.","Repeat for the desired number of repetitions, then switch sides and perform with your right hand."]', '["एक केबल हैंडल को निचली पुली से जोड़ें और मशीन की ओर मुंह करके खड़े हो जाएं।","अपने बाएं हाथ से हैंडल को पकड़ें और अपने हाथ को पूरी तरह फैलाते हुए मशीन से दूर हट जाएं।","अपने पैरों को कंधे की चौड़ाई से अलग रखें, आपके घुटने थोड़े मुड़े हुए हों।","पूरे अभ्यास के दौरान अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","ऐसा करते समय अपने धड़ को दाईं ओर घुमाते हुए, हैंडल को अपने शरीर की ओर खींचें।","आंदोलन के अंत में अपनी पीठ की मांसपेशियों को निचोड़ें।","केबल पर तनाव बनाए रखते हुए धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें और अपने दाहिने हाथ से प्रदर्शन करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1645', 'Cable Two Arm Curl On Incline Bench', 'upper arms', 'biceps', '["forearms"]', 'cable', 'strength', NULL, '["Sit on an incline bench with your back against the pad and your feet flat on the ground.","Grasp the cable handles with an underhand grip, palms facing up, and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the handles towards your shoulders while contracting your biceps.","Pause for a moment at the top of the movement, squeezing your biceps.","Inhale and slowly lower the handles back to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["एक झुकी हुई बेंच पर अपनी पीठ पैड से सटाकर और अपने पैरों को ज़मीन पर सपाट करके बैठें।","केबल के हैंडल को अंडरहैंड ग्रिप से पकड़ें, हथेलियाँ ऊपर की ओर हों और आपकी भुजाएँ पूरी तरह फैली हुई हों।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए हैंडल को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए, गति के शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे अपनी बाहों को पूरी तरह फैलाते हुए हैंडल को शुरुआती स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1728', 'Cable Two Arm Tricep Kickback', 'upper arms', 'triceps', '["shoulders"]', 'cable', 'strength', NULL, '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Keeping your upper arms stationary, extend your forearms backwards until your arms are fully extended.","Pause for a moment, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","अपनी हथेलियों को अंदर की ओर रखते हुए और अपनी बाहों को 90 डिग्री के कोण पर मोड़कर प्रत्येक हाथ में केबल के हैंडल को पकड़ें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपने अग्र भुजाओं को पीछे की ओर तब तक फैलाएँ जब तक कि आपकी भुजाएँ पूरी तरह विस्तारित न हो जाएँ।","एक पल के लिए रुकें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0245', 'Cable Underhand Pulldown', 'back', 'lats', '["biceps","forearms"]', 'cable', 'strength', 'beginner', '["Adjust the cable machine so that the pulldown bar is at a height above your head.","Sit down on the seat and grab the pulldown bar with an underhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and lean back slightly.","Pull the bar down towards your chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन को इस प्रकार समायोजित करें कि पुलडाउन बार आपके सिर से ऊंचाई पर हो।","सीट पर बैठ जाएं और पुलडाउन बार को हाथ से पकड़ें, हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","अपनी पीठ सीधी रखें और थोड़ा पीछे झुकें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बार को अपनी छाती की ओर नीचे खींचें।","गति के निचले भाग पर एक क्षण के लिए रुकें, फिर धीरे-धीरे बार को प्रारंभिक स्थिति में वापस छोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Underhand_Cable_Pulldowns/0.jpg","Underhand_Cable_Pulldowns/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1270', 'Cable Upper Chest Crossovers', 'chest', 'pectorals', '["deltoids","triceps"]', 'cable', 'strength', NULL, '["Attach the handles to the cables at chest height.","Stand in the center of the cable machine with one foot slightly in front of the other.","Grasp the handles with your palms facing down and your arms extended out to the sides.","Keep a slight bend in your elbows and engage your core.","Pull the cables together in front of your chest, crossing them over each other.","Squeeze your chest muscles at the peak of the movement.","Slowly release the cables back to the starting position.","Repeat for the desired number of repetitions."]', '["हैंडल को केबल से छाती की ऊंचाई पर जोड़ें।","केबल मशीन के केंद्र में एक पैर दूसरे के सामने थोड़ा सा रखकर खड़े हो जाएं।","अपनी हथेलियों को नीचे की ओर रखते हुए और अपनी बाहों को बगल की ओर फैलाकर हैंडल को पकड़ें।","अपनी कोहनियों को थोड़ा मोड़ें और अपने कोर को संलग्न रखें।","केबलों को अपनी छाती के सामने एक-दूसरे के ऊपर से क्रॉस करते हुए खींचें।","आंदोलन के चरम पर अपनी छाती की मांसपेशियों को निचोड़ें।","धीरे-धीरे केबलों को वापस प्रारंभिक स्थिति में छोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1324', 'Cable Upper Row', 'back', 'upper back', '["biceps","shoulders"]', 'cable', 'strength', NULL, '["Attach a straight bar to a cable machine at chest height.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.","Keep your back straight and your core engaged.","Pull the bar towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the top of the movement.","Slowly release the bar back to the starting position.","Repeat for the desired number of repetitions."]', '["एक सीधी पट्टी को केबल मशीन से छाती की ऊंचाई पर जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","बार को ओवरहैंड ग्रिप से पकड़ें, हाथ कंधे की चौड़ाई से थोड़े चौड़े हों।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बार को अपनी ऊपरी छाती की ओर खींचें।","गति के शीर्ष पर एक क्षण के लिए रुकें।","धीरे-धीरे बार को प्रारंभिक स्थिति में वापस छोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0246', 'Cable Upright Row', 'shoulders', 'delts', '["traps","biceps"]', 'cable', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, knees slightly bent, and hold the cable attachment with an overhand grip.","Keep your back straight and your core engaged throughout the exercise.","Pull the cable attachment straight up towards your chin, leading with your elbows.","Pause for a moment at the top, squeezing your shoulder blades together.","Slowly lower the cable attachment back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, घुटने थोड़े मुड़े हुए हों और केबल अटैचमेंट को ओवरहैंड ग्रिप से पकड़ें।","पूरे अभ्यास के दौरान अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","केबल अटैचमेंट को अपनी कोहनियों से आगे बढ़ाते हुए सीधे अपनी ठुड्डी की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, अपने कंधे के ब्लेड को एक साथ दबाएं।","धीरे-धीरे केबल अटैचमेंट को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Upright_Cable_Row/0.jpg","Upright_Cable_Row/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1325', 'Cable Wide Grip Rear Pulldown Behind Neck', 'back', 'lats', '["biceps","rhomboids","rear deltoids"]', 'cable', 'strength', NULL, '["Adjust the cable machine so that the pulldown bar is at a height above your head.","Sit down on the seat and grab the pulldown bar with a wide overhand grip.","Keep your back straight and your chest up as you lean back slightly.","Pull the bar down towards your upper chest, squeezing your shoulder blades together.","Pause for a moment at the bottom of the movement, then slowly release the bar back up to the starting position.","Repeat for the desired number of repetitions."]', '["केबल मशीन को इस प्रकार समायोजित करें कि पुलडाउन बार आपके सिर से ऊंचाई पर हो।","सीट पर बैठ जाएं और पुलडाउन बार को चौड़ी पकड़ से पकड़ें।","थोड़ा पीछे झुकते समय अपनी पीठ सीधी रखें और अपनी छाती ऊपर रखें।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बार को अपनी ऊपरी छाती की ओर नीचे खींचें।","गति के निचले भाग पर एक क्षण के लिए रुकें, फिर धीरे-धीरे बार को प्रारंभिक स्थिति में वापस छोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0247', 'Cable Wrist Curl', 'lower arms', 'forearms', '["biceps","brachialis"]', 'cable', 'strength', 'beginner', '["Attach a straight bar to a low pulley cable machine.","Stand facing the machine with your feet shoulder-width apart.","Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.","Rest your forearms on a bench or pad, with your wrists hanging off the edge.","Keeping your forearms stationary, exhale and curl your wrists upward as far as possible.","Pause for a moment at the top, then inhale and slowly lower the bar back to the starting position.","Repeat for the desired number of repetitions."]', '["लो पुली केबल मशीन में एक सीधी पट्टी जोड़ें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए मशीन की ओर मुंह करके खड़े हो जाएं।","बार को अंडरहैंड ग्रिप से पकड़ें, हथेलियाँ ऊपर की ओर हों और आपके हाथ कंधे की चौड़ाई से अलग हों।","अपनी कलाईयों को किनारे से लटकाते हुए अपने अग्रबाहुओं को एक बेंच या पैड पर रखें।","अपनी बांहों को स्थिर रखते हुए सांस छोड़ें और जहां तक ​​संभव हो अपनी कलाइयों को ऊपर की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे बार को प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Cable_Wrist_Curl/0.jpg","Cable_Wrist_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1407', 'Calf Push Stretch With Hands Against Wall', 'lower legs', 'calves', '["hamstrings"]', 'body weight', 'strength', NULL, '["Stand facing a wall with your feet hip-width apart.","Place your hands against the wall at shoulder height.","Step back with one foot, keeping your heel on the ground and your leg straight.","Bend your front knee slightly and lean forward, feeling a stretch in your calf.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."]', '["अपने पैरों को कूल्हे की चौड़ाई की दूरी पर रखते हुए दीवार की ओर मुंह करके खड़े हो जाएं।","अपने हाथों को कंधे की ऊंचाई पर दीवार से सटाकर रखें।","एक पैर से पीछे हटें, अपनी एड़ी को ज़मीन पर रखें और अपने पैर को सीधा रखें।","अपने सामने के घुटने को थोड़ा मोड़ें और अपनी पिंडली में खिंचाव महसूस करते हुए आगे की ओर झुकें।","20-30 सेकंड तक खिंचाव बनाए रखें।","पैर बदलें और खिंचाव दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1377', 'Calf Stretch With Hands Against Wall', 'lower legs', 'calves', '["hamstrings"]', 'body weight', 'strength', NULL, '["Stand facing a wall with your feet hip-width apart.","Place your hands against the wall at shoulder height.","Step your right foot back, keeping your heel on the ground and your leg straight.","Bend your left knee and lean forward, keeping your back leg straight and your heel on the ground.","Hold the stretch for 20-30 seconds.","Switch legs and repeat the stretch."]', '["अपने पैरों को कूल्हे की चौड़ाई की दूरी पर रखते हुए दीवार की ओर मुंह करके खड़े हो जाएं।","अपने हाथों को कंधे की ऊंचाई पर दीवार से सटाकर रखें।","अपने दाहिने पैर को पीछे ले जाएं, अपनी एड़ी को ज़मीन पर रखें और अपने पैर को सीधा रखें।","अपने बाएं घुटने को मोड़ें और आगे की ओर झुकें, अपने पिछले पैर को सीधा रखें और अपनी एड़ी को ज़मीन पर रखें।","20-30 सेकंड तक खिंचाव बनाए रखें।","पैर बदलें और खिंचाव दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1378', 'Calf Stretch With Rope', 'lower legs', 'calves', '["hamstrings"]', 'rope', 'strength', NULL, '["Stand facing a wall or sturdy object with your feet hip-width apart.","Hold the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.","Step back with your left foot, keeping your heel on the ground and your leg straight.","Lean forward, keeping your back straight, and gently pull on the rope to stretch your calf.","Hold the stretch for 20-30 seconds, then release.","Repeat on the other leg."]', '["अपने पैरों को कूल्हे की चौड़ाई की दूरी पर रखते हुए किसी दीवार या मजबूत वस्तु की ओर मुंह करके खड़े हो जाएं।","प्रत्येक हाथ में रस्सी के सिरों को पकड़ें और रस्सी के मध्य भाग को अपने दाहिने पैर की गेंद के चारों ओर रखें।","अपने बाएं पैर से पीछे हटें, अपनी एड़ी को ज़मीन पर रखें और अपने पैर को सीधा रखें।","अपनी पीठ सीधी रखते हुए आगे झुकें और अपने पिंडली को फैलाने के लिए रस्सी को धीरे से खींचें।","20-30 सेकंड तक खिंचाव बनाए रखें, फिर छोड़ें।","दूसरे पैर पर दोहराएँ."]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0248', 'Cambered Bar Lying Row', 'back', 'upper back', '["biceps","forearms"]', 'barbell', 'strength', NULL, '["Set up a barbell on the floor and lie face down on a bench with your chest just off the edge.","Reach down and grab the barbell with an overhand grip, slightly wider than shoulder-width apart.","With your legs straight and feet on the ground, lift the barbell off the floor by extending your arms.","Pull the barbell towards your chest, squeezing your shoulder blades together.","Lower the barbell back down to the starting position and repeat for the desired number of repetitions."]', '["फर्श पर एक बारबेल स्थापित करें और अपनी छाती को किनारे से थोड़ा दूर रखते हुए एक बेंच पर मुंह करके लेट जाएं।","नीचे पहुंचें और बारबेल को कंधे की चौड़ाई से थोड़ा अधिक चौड़ी पकड़ के साथ पकड़ें।","अपने पैरों को सीधा और पैरों को जमीन पर रखते हुए, अपनी बाहों को फैलाकर बारबेल को फर्श से उठाएं।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, बारबेल को अपनी छाती की ओर खींचें।","बारबेल को वापस प्रारंभिक स्थिति में लाएँ और वांछित संख्या में दोहराव के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2963', 'Captains Chair Straight Leg Raise', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Sit on the captain''s chair with your back against the backrest and your forearms resting on the arm pads.","Keep your upper body stable and your back straight.","Engage your abs and lift your legs up in front of you, keeping them straight.","Continue lifting until your legs are parallel to the ground or as high as you can comfortably go.","Pause for a moment at the top, then slowly lower your legs back down to the starting position.","Repeat for the desired number of repetitions."]', '["कैप्टन की कुर्सी पर अपनी पीठ बैकरेस्ट के सामने रखकर और अपने अग्रबाहुओं को आर्म पैड पर टिकाकर बैठें।","अपने ऊपरी शरीर को स्थिर रखें और अपनी पीठ को सीधा रखें।","अपने पेट को संलग्न करें और अपने पैरों को अपने सामने ऊपर उठाएं, उन्हें सीधा रखें।","तब तक उठाना जारी रखें जब तक कि आपके पैर जमीन के समानांतर या उतने ऊपर न आ जाएं जितना आप आराम से जा सकें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने पैरों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1548', 'Chair Leg Extended Stretch', 'upper legs', 'quads', '["hamstrings","calves"]', 'body weight', 'strength', NULL, '["Sit on the edge of a chair with your back straight and feet flat on the ground.","Extend one leg straight out in front of you, keeping your heel on the ground.","Lean forward slightly, feeling a stretch in your quadriceps.","Hold this position for 20-30 seconds.","Switch legs and repeat the stretch."]', '["कुर्सी के किनारे पर अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके बैठें।","अपनी एड़ी को ज़मीन पर रखते हुए एक पैर को अपने सामने सीधा फैलाएँ।","अपने क्वाड्रिसेप्स में खिंचाव महसूस करते हुए थोड़ा आगे झुकें।","इस स्थिति में 20-30 सेकंड तक रुकें।","पैर बदलें और खिंचाव दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1271', 'Chest And Front Of Shoulder Stretch', 'chest', 'pectorals', '["deltoids"]', 'body weight', 'strength', NULL, '["Stand tall with your feet shoulder-width apart.","Extend your arms straight out in front of you at shoulder height.","Cross your arms in front of your body, with your right arm on top of your left arm.","Interlace your fingers and press your palms together.","Gently squeeze your shoulder blades together and push your hands forward, feeling a stretch in your chest and front of your shoulders.","Hold the stretch for 20-30 seconds, then release.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े रहें।","अपनी बाहों को कंधे की ऊंचाई पर अपने सामने सीधा फैलाएं।","अपनी भुजाओं को अपने शरीर के सामने क्रॉस करें, अपनी दायीं भुजा को अपनी बायीं भुजा के ऊपर रखें।","अपनी उंगलियों को आपस में मिलाएं और अपनी हथेलियों को एक साथ दबाएं।","धीरे से अपने कंधे के ब्लेड को एक साथ दबाएं और अपने हाथों को आगे की ओर धकेलें, अपनी छाती और अपने कंधों के सामने खिंचाव महसूस करें।","20-30 सेकंड तक खिंचाव बनाए रखें, फिर छोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0251', 'Chest Dip', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Position yourself on parallel bars with your arms fully extended and your body straight.","Lower your body by bending your elbows until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["अपनी भुजाओं को पूरी तरह फैलाकर और अपने शरीर को सीधा रखते हुए अपने आप को समानांतर सलाखों पर रखें।","अपनी कोहनियों को मोड़कर अपने शरीर को तब तक नीचे लाएँ जब तक कि आपके कंधे आपकी कोहनियों से नीचे न आ जाएँ।","अपनी भुजाओं को सीधा करके स्वयं को प्रारंभिक स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-1430', 'Chest Dip (On Dip-Pull-Up Cage)', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Adjust the dip bars to a height that allows you to comfortably grip them.","Stand between the bars and place your hands on each bar, slightly wider than shoulder-width apart.","Jump up and straighten your arms, supporting your body weight on the bars.","Bend your knees and cross your ankles behind you.","Lower your body by bending your elbows, keeping your chest up and your shoulders down.","Continue lowering until your shoulders are below your elbows or until you feel a stretch in your chest.","Push through your palms and extend your elbows to raise your body back up to the starting position.","Repeat for the desired number of repetitions."]', '["डिप बार को इतनी ऊंचाई पर समायोजित करें कि आप उन्हें आराम से पकड़ सकें।","सलाखों के बीच खड़े हो जाएं और अपने हाथों को प्रत्येक पट्टी पर कंधे की चौड़ाई से थोड़ा अधिक फैलाकर रखें।","ऊपर कूदें और अपनी बाहों को सीधा करें, अपने शरीर के वजन को सलाखों पर सहारा दें।","अपने घुटनों को मोड़ें और अपनी एड़ियों को अपने पीछे क्रॉस करें।","अपनी कोहनियों को मोड़कर, अपनी छाती को ऊपर और अपने कंधों को नीचे रखते हुए अपने शरीर को नीचे करें।","जब तक आपके कंधे आपकी कोहनी से नीचे न आ जाएं या जब तक आप अपनी छाती में खिंचाव महसूस न करें तब तक नीचे झुकना जारी रखें।","अपने शरीर को प्रारंभिक स्थिति में वापस उठाने के लिए अपनी हथेलियों से धक्का दें और अपनी कोहनियों को फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2462', 'Chest Dip On Straight Bar', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Grab the parallel bars with your palms facing down and your arms fully extended.","Bend your knees and cross your ankles.","Lower your body by bending your arms until your shoulders are below your elbows.","Push yourself back up to the starting position by straightening your arms.","Repeat for the desired number of repetitions."]', '["अपनी हथेलियों को नीचे की ओर रखते हुए और अपनी भुजाओं को पूरी तरह फैलाकर समानांतर पट्टियों को पकड़ें।","अपने घुटनों को मोड़ें और अपनी एड़ियों को क्रॉस करें।","अपनी भुजाओं को झुकाकर अपने शरीर को तब तक नीचे लाएँ जब तक कि आपके कंधे आपकी कोहनी से नीचे न आ जाएँ।","अपनी भुजाओं को सीधा करके स्वयं को प्रारंभिक स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1272', 'Chest Stretch With Exercise Ball', 'chest', 'pectorals', '["shoulders","triceps"]', 'stability ball', 'strength', NULL, '["Sit on the stability ball with your feet flat on the ground and your back straight.","Hold the exercise ball with both hands and extend your arms straight out in front of you.","Slowly bring the exercise ball towards your chest, feeling a stretch in your chest muscles.","Hold the stretch for a few seconds, then slowly return to the starting position.","Repeat for the desired number of repetitions."]', '["स्टेबिलिटी बॉल पर अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा करके बैठें।","एक्सरसाइज बॉल को दोनों हाथों से पकड़ें और अपनी बाहों को अपने सामने सीधा फैलाएं।","अपनी छाती की मांसपेशियों में खिंचाव महसूस करते हुए धीरे-धीरे व्यायाम गेंद को अपनी छाती की ओर लाएँ।","कुछ सेकंड के लिए खिंचाव बनाए रखें, फिर धीरे-धीरे प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3216', 'Chest Tap Push-Up (Male)', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you lower yourself, tap your chest with your right hand.","Push yourself back up to the starting position.","Repeat the movement, this time tapping your chest with your left hand.","Continue alternating sides for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक चौड़ा करके और अपने शरीर को एक सीधी रेखा में रखते हुए एक उच्च तख़्त स्थिति में शुरुआत करें।","अपनी कोहनियों को मोड़कर, उन्हें अपनी भुजाओं के पास रखते हुए, अपने शरीर को ज़मीन की ओर नीचे लाएँ।","जैसे ही आप खुद को नीचे करें, अपने दाहिने हाथ से अपनी छाती को थपथपाएं।","अपने आप को वापस प्रारंभिक स्थिति में धकेलें।","इस क्रिया को दोहराएँ, इस बार अपने बाएँ हाथ से अपनी छाती को थपथपाएँ।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1326', 'Chin-Up', 'back', 'lats', '["biceps","forearms"]', 'body weight', 'strength', 'beginner', '["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Engage your core and pull your body up towards the bar, leading with your chest.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी हथेलियों को अपनी ओर रखते हुए और अपने हाथों को कंधे की चौड़ाई से अलग रखते हुए पुल-अप बार से लटकें।","अपने कोर को संलग्न करें और अपने शरीर को अपनी छाती की ओर ले जाते हुए बार की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी बार के ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Chin-Up/0.jpg","Chin-Up/1.jpg"]', 5, 'sets', 1, 'opengym', 1),
('og-0253', 'Chin-Ups (Narrow Parallel Grip)', 'back', 'upper back', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Hang from a pull-up bar with a narrow parallel grip, palms facing towards you.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक संकीर्ण समानांतर पकड़ के साथ पुल-अप बार से लटकें, हथेलियाँ आपकी ओर हों।","अपनी पीठ की मांसपेशियों को शामिल करें और अपनी कोहनियों को अपने शरीर के करीब रखते हुए अपने शरीर को बार की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी बार के ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0257', 'Circles Knee Stretch', 'lower legs', 'calves', '["hamstrings","quadriceps"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart and your hands on your hips.","Bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet.","Keeping your knees bent, rotate your knees in a circular motion, first clockwise and then counterclockwise.","Perform the movement for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर और अपने हाथों को अपने कूल्हों पर रखकर खड़े हो जाएं।","अपने घुटनों को थोड़ा मोड़ें और अपने पैरों की उंगलियों पर संतुलन बनाते हुए अपनी एड़ियों को ज़मीन से ऊपर उठाएं।","अपने घुटनों को मोड़ते हुए, अपने घुटनों को गोलाकार गति में घुमाएँ, पहले दक्षिणावर्त और फिर वामावर्त।","दोहराव की वांछित संख्या के लिए आंदोलन करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1273', 'Clap Push Up', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your body towards the ground by bending your elbows, keeping your core engaged.","Push through your palms explosively to propel your body off the ground.","While in mid-air, clap your hands together before landing back in the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखते हुए एक ऊंचे तख़्ते की स्थिति से शुरुआत करें।","अपनी कोहनियों को मोड़कर, अपने कोर को व्यस्त रखते हुए, अपने शरीर को ज़मीन की ओर नीचे लाएँ।","अपने शरीर को ज़मीन से ऊपर उठाने के लिए अपनी हथेलियों से ज़ोर से धक्का दें।","मध्य हवा में रहते हुए, प्रारंभिक स्थिति में वापस आने से पहले अपने हाथों को एक साथ ताली बजाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0258', 'Clock Push-Up', 'chest', 'pectorals', '["triceps","shoulders","core"]', 'body weight', 'strength', 'intermediate', '["Start in a high plank position with your hands directly under your shoulders and your body in a straight line.","Lower your body towards the ground by bending your elbows, keeping them close to your sides.","As you lower, rotate your body to the left, extending your left arm straight out to the side.","Push back up to the starting position, while rotating your body to the center.","Repeat the push-up, this time rotating your body to the right and extending your right arm out to the side.","Continue alternating sides with each repetition."]', '["अपने हाथों को सीधे अपने कंधों के नीचे और अपने शरीर को एक सीधी रेखा में रखते हुए एक उच्च तख़्त स्थिति में शुरुआत करें।","अपनी कोहनियों को मोड़कर, उन्हें अपनी भुजाओं के पास रखते हुए, अपने शरीर को ज़मीन की ओर नीचे लाएँ।","जैसे ही आप नीचे आते हैं, अपने शरीर को बाईं ओर घुमाएं, अपने बाएं हाथ को सीधा बगल की ओर फैलाएं।","अपने शरीर को केंद्र की ओर घुमाते हुए, प्रारंभिक स्थिति में वापस आएँ।","पुश-अप को दोहराएं, इस बार अपने शरीर को दाईं ओर घुमाएं और अपने दाहिने हाथ को बगल की ओर फैलाएं।","प्रत्येक पुनरावृत्ति के साथ पक्षों को बदलना जारी रखें।"]', '["Clock_Push-Up/0.jpg","Clock_Push-Up/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1327', 'Close Grip Chin-Up', 'back', 'lats', '["biceps","forearms"]', 'body weight', 'strength', NULL, '["Grab the pull-up bar with your palms facing towards you and your hands shoulder-width apart.","Hang from the bar with your arms fully extended and your feet off the ground.","Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.","Continue pulling until your chin is above the bar.","Pause for a moment at the top, then slowly lower your body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी हथेलियों को अपनी ओर रखते हुए और अपने हाथों को कंधे की चौड़ाई से अलग रखते हुए पुल-अप बार को पकड़ें।","अपनी बाहों को पूरी तरह फैलाकर और अपने पैरों को ज़मीन से ऊपर रखते हुए बार से लटकें।","अपनी पीठ की मांसपेशियों को शामिल करें और अपनी कोहनियों को अपने शरीर के करीब रखते हुए अपने शरीर को बार की ओर ऊपर खींचें।","तब तक खींचते रहें जब तक आपकी ठुड्डी बार के ऊपर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0259', 'Close-Grip Push-Up', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', NULL, '["Start in a high plank position with your hands placed close together, directly under your shoulders.","Engage your core and lower your body towards the ground, keeping your elbows close to your sides.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को एक-दूसरे के करीब, सीधे अपने कंधों के नीचे रखते हुए एक ऊंची तख़्त स्थिति में शुरुआत करें।","अपने कोर को संलग्न करें और अपने शरीर को ज़मीन की ओर नीचे करें, अपनी कोहनियों को अपने किनारों के पास रखें।","अपनी हथेलियों से धक्का देकर अपनी भुजाओं को फैलाएं और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2398', 'Close-Grip Push-Up (On Knees)', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', NULL, '["Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.","Lower your upper body towards the ground by bending your elbows, keeping them close to your sides.","Pause for a moment when your chest is just above the ground.","Push through your palms to straighten your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों और घुटनों के बल खड़े होकर शुरुआत करें, अपने हाथों को कंधे की चौड़ाई पर और घुटनों को कूल्हे की चौड़ाई पर अलग रखें।","अपनी कोहनियों को मोड़कर, उन्हें अपनी भुजाओं के पास रखते हुए, अपने ऊपरी शरीर को ज़मीन की ओर नीचे लाएँ।","जब आपकी छाती ज़मीन से ठीक ऊपर हो तो एक पल के लिए रुकें।","अपनी भुजाओं को सीधा करने के लिए अपनी हथेलियों से धक्का दें और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0260', 'Cocoons', 'waist', 'abs', '["hip flexors","lower back"]', 'body weight', 'strength', 'beginner', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Cocoons/0.jpg","Cocoons/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1468', 'Crab Twist Toe Touch', 'waist', 'abs', '["obliques","hip flexors"]', 'body weight', 'strength', NULL, '["Start by sitting on the ground with your knees bent and feet flat on the floor.","Place your hands behind you, fingers pointing towards your feet, and lift your hips off the ground.","Extend one leg straight out in front of you while simultaneously reaching your opposite hand towards your toes.","Return to the starting position and repeat on the other side.","Continue alternating sides for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को फर्श पर सपाट करके जमीन पर बैठकर शुरुआत करें।","अपने हाथों को अपने पीछे रखें, उंगलियाँ आपके पैरों की ओर हों, और अपने कूल्हों को ज़मीन से ऊपर उठाएँ।","एक पैर को अपने सामने सीधा फैलाएं और साथ ही अपने उल्टे हाथ को अपने पैर की उंगलियों तक पहुंचाएं।","प्रारंभिक स्थिति पर लौटें और दूसरी तरफ दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0262', 'Cross Body Crunch', 'waist', 'abs', '["obliques"]', 'body weight', 'strength', 'beginner', '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, lift your upper body off the ground and twist to bring your right elbow towards your left knee.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat on the other side, bringing your left elbow towards your right knee.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को जोड़ते हुए, अपने ऊपरी शरीर को जमीन से ऊपर उठाएं और अपनी दाहिनी कोहनी को अपने बाएं घुटने की ओर लाने के लिए मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","अपनी बाईं कोहनी को अपने दाहिने घुटने की ओर लाते हुए दूसरी तरफ दोहराएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Cross-Body_Crunch/0.jpg","Cross-Body_Crunch/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0267', 'Crunch (Hands Overhead)', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', 'beginner', '["Lie flat on your back with your knees bent and feet flat on the ground.","Extend your arms straight above your head.","Engaging your abs, lift your upper body off the ground, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपनी बाहों को सीधे अपने सिर के ऊपर फैलाएँ।","अपने पेट को जोड़ते हुए, अपने ऊपरी शरीर को ज़मीन से ऊपर उठाएं, अपने घुटनों की ओर आगे की ओर झुकें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Crunch_-_Hands_Overhead/0.jpg","Crunch_-_Hands_Overhead/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0271', 'Crunch (On Stability Ball)', 'waist', 'abs', '["hip flexors"]', 'stability ball', 'strength', NULL, '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body towards your knees, curling your torso forward.","Pause for a moment at the top of the movement, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्टेबिलिटी बॉल पर अपने पैरों को ज़मीन पर सपाट करके बैठें और आपके घुटने 90 डिग्री के कोण पर मुड़े हों।","गेंद पर तब तक लेटें जब तक कि आपकी निचली पीठ को सहारा न मिल जाए और आपका ऊपरी शरीर फर्श के समानांतर न हो जाए।","अपने हाथों को अपने सिर के पीछे या अपनी छाती के पार रखें।","अपने पेट को संलग्न करें और अपने ऊपरी शरीर को अपने घुटनों की ओर उठाएं, अपने धड़ को आगे की ओर मोड़ें।","गति के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0272', 'Crunch (On Stability Ball, Arms Straight)', 'waist', 'abs', '["hip flexors"]', 'stability ball', 'strength', NULL, '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Lie back on the ball until your lower back is supported and your upper body is parallel to the floor.","Place your hands behind your head or cross them over your chest.","Engage your abs and lift your upper body off the ball, curling your shoulders towards your hips.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["स्टेबिलिटी बॉल पर अपने पैरों को ज़मीन पर सपाट करके बैठें और आपके घुटने 90 डिग्री के कोण पर मुड़े हों।","गेंद पर तब तक लेटें जब तक कि आपकी निचली पीठ को सहारा न मिल जाए और आपका ऊपरी शरीर फर्श के समानांतर न हो जाए।","अपने हाथों को अपने सिर के पीछे रखें या उन्हें अपनी छाती के ऊपर से पार करें।","अपने पेट को संलग्न करें और अपने ऊपरी शरीर को गेंद से ऊपर उठाएं, अपने कंधों को अपने कूल्हों की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0274', 'Crunch Floor', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engage your abs and lift your shoulders off the ground, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को संलग्न करें और अपने कंधों को जमीन से ऊपर उठाएं, अपने घुटनों की ओर आगे की ओर झुकें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने कंधों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-3016', 'Curl-Up', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', NULL, '["Lie flat on your back with your knees bent and feet flat on the ground.","Place your hands behind your head with your elbows pointing outwards.","Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने घुटनों को मोड़कर और पैरों को ज़मीन पर सपाट रखते हुए अपनी पीठ के बल लेट जाएँ।","अपने हाथों को अपने सिर के पीछे रखें और अपनी कोहनियों को बाहर की ओर रखें।","अपने पेट को शामिल करते हुए, धीरे-धीरे अपने ऊपरी शरीर को जमीन से ऊपर उठाएं, आगे की ओर झुकें जब तक कि आपका धड़ 45 डिग्री के कोण पर न आ जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3769', 'Curtsey Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'body weight', 'strength', NULL, '["Stand with your feet shoulder-width apart.","Take a step diagonally behind and across your body with your right foot, crossing it behind your left leg.","Bend both knees as if you were curtsying, lowering your body towards the ground.","Keep your torso upright and your weight on your front foot.","Push through your front foot to return to the starting position.","Repeat on the other side, stepping diagonally behind and across your body with your left foot."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर रखकर खड़े हो जाएं।","अपने दाहिने पैर को अपने बाएं पैर के पीछे से पार करते हुए, अपने शरीर के पीछे और तिरछे एक कदम उठाएं।","दोनों घुटनों को मोड़ें जैसे कि आप कर्टसी कर रहे हों, अपने शरीर को ज़मीन की ओर झुकाएँ।","अपने धड़ को सीधा रखें और अपना वजन अपने सामने वाले पैर पर रखें।","प्रारंभिक स्थिति में लौटने के लिए अपने सामने वाले पैर से धक्का दें।","दूसरी तरफ दोहराएँ, अपने बाएँ पैर से अपने शरीर के पीछे और आर-पार तिरछे कदम बढ़ाते हुए।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2331', 'Cycle Cross Trainer', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","glutes"]', 'leverage machine', 'cardio', NULL, '["Adjust the seat height and position yourself on the cycle cross trainer.","Place your feet on the pedals and grip the handlebars.","Start pedaling in a smooth and controlled motion.","Maintain a steady pace and increase the resistance if desired.","Continue pedaling for the desired duration of your cardio workout."]', '["सीट की ऊंचाई समायोजित करें और अपने आप को साइकिल क्रॉस ट्रेनर पर रखें।","अपने पैरों को पैडल पर रखें और हैंडलबार को पकड़ें।","सहज और नियंत्रित गति में पैडल चलाना शुरू करें।","स्थिर गति बनाए रखें और यदि चाहें तो प्रतिरोध बढ़ाएँ।","अपने कार्डियो वर्कआउट की वांछित अवधि तक पैडल चलाना जारी रखें।"]', NULL, 7.5, 'time', 0, 'opengym', 1),
('og-0276', 'Dead Bug', 'waist', 'abs', '["hip flexors","lower back"]', 'body weight', 'strength', 'beginner', '["Lie flat on your back with your arms extended towards the ceiling.","Bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.","Engage your core and lower back to press your lower back into the ground.","Slowly lower your right arm and left leg towards the ground, keeping them straight and hovering just above the floor.","Pause for a moment, then return to the starting position.","Repeat the movement with your left arm and right leg.","Continue alternating sides for the desired number of repetitions."]', '["अपनी पीठ के बल सीधे लेट जाएँ और अपनी बाँहों को छत की ओर फैलाएँ।","अपने घुटनों को मोड़ें और अपने पैरों को ज़मीन से ऊपर उठाएं, जिससे आपके कूल्हों और घुटनों पर 90 डिग्री का कोण बन जाए।","अपनी पीठ के निचले हिस्से को ज़मीन पर दबाने के लिए अपने कोर और पीठ के निचले हिस्से को संलग्न करें।","अपने दाहिने हाथ और बाएं पैर को धीरे-धीरे जमीन की ओर नीचे लाएं, उन्हें सीधा रखें और फर्श के ठीक ऊपर रखें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौट आएं।","इस क्रिया को अपने बाएँ हाथ और दाएँ पैर से दोहराएँ।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', '["Dead_Bug/0.jpg","Dead_Bug/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0277', 'Decline Crunch', 'waist', 'abs', '["hip flexors"]', 'body weight', 'strength', 'intermediate', '["Lie on a decline bench with your feet secured and your knees bent at a 90-degree angle.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body towards your knees, curling your torso.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को सुरक्षित रखते हुए और अपने घुटनों को 90 डिग्री के कोण पर मोड़कर एक डिक्लाइन बेंच पर लेटें।","अपने हाथों को अपने सिर के पीछे या अपनी छाती के पार रखें।","अपने पेट को संलग्न करें और अपने धड़ को मोड़ते हुए अपने ऊपरी शरीर को अपने घुटनों की ओर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Decline_Crunch/0.jpg","Decline_Crunch/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0279', 'Decline Push-Up', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Place your hands on the ground slightly wider than shoulder-width apart, with your feet elevated on a stable surface.","Keep your body in a straight line from head to toe, engaging your core muscles.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक दूरी पर जमीन पर रखें, अपने पैरों को एक स्थिर सतह पर ऊंचा रखें।","अपने शरीर को सिर से पैर तक एक सीधी रेखा में रखें, अपनी मुख्य मांसपेशियों को शामिल करते हुए।","अपनी कोहनियों को मोड़कर, उन्हें अपने शरीर के पास रखते हुए, अपनी छाती को ज़मीन की ओर नीचे करें।","अपनी हथेलियों से धक्का देकर अपनी भुजाओं को फैलाएं और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0282', 'Decline Sit-Up', 'waist', 'abs', '["hip flexors","lower back"]', 'body weight', 'strength', NULL, '["Lie on a decline bench with your feet secured and your knees bent.","Place your hands behind your head or across your chest.","Engage your abs and lift your upper body off the bench, curling forward towards your knees.","Pause for a moment at the top, then slowly lower your upper body back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को सुरक्षित रखते हुए और घुटनों को मोड़कर एक डिक्लाइन बेंच पर लेटें।","अपने हाथों को अपने सिर के पीछे या अपनी छाती के पार रखें।","अपने पेट को संलग्न करें और अपने ऊपरी शरीर को बेंच से ऊपर उठाएं, अपने घुटनों की ओर आगे की ओर झुकें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने ऊपरी शरीर को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1274', 'Deep Push Up', 'chest', 'pectorals', '["triceps","shoulders"]', 'dumbbell', 'strength', NULL, '["Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line.","Lower your chest towards the ground by bending your elbows, keeping them close to your body.","Push through your palms to extend your arms and return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा अधिक चौड़ा करके और अपने शरीर को एक सीधी रेखा में रखते हुए एक उच्च तख़्त स्थिति में शुरुआत करें।","अपनी कोहनियों को मोड़कर, उन्हें अपने शरीर के पास रखते हुए, अपनी छाती को ज़मीन की ओर नीचे करें।","अपनी हथेलियों से धक्का देकर अपनी भुजाओं को फैलाएं और प्रारंभिक स्थिति में लौट आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0283', 'Diamond Push-Up', 'upper arms', 'triceps', '["chest","shoulders"]', 'body weight', 'strength', NULL, '["Start in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers.","Keep your body in a straight line from head to toe, engaging your core and glutes.","Lower your chest towards the diamond shape formed by your hands, keeping your elbows close to your body.","Pause for a moment at the bottom, then push yourself back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने हाथों को एक साथ पास करके, अपने अंगूठे और तर्जनी के साथ एक हीरे की आकृति बनाते हुए, एक उच्च तख़्त स्थिति में शुरुआत करें।","अपने शरीर को सिर से पैर तक एक सीधी रेखा में रखें, अपने कोर और ग्लूट्स को शामिल करते हुए।","अपनी कोहनियों को अपने शरीर के पास रखते हुए, अपनी छाती को अपने हाथों से बने हीरे के आकार की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर अपने आप को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0284', 'Donkey Calf Raise', 'lower legs', 'calves', '["hamstrings","glutes"]', 'body weight', 'strength', NULL, '["Stand with your toes on an elevated surface, such as a step or block.","Place your hands on a stable support, such as a wall or railing, for balance.","Raise your heels as high as possible, lifting your body weight onto the balls of your feet.","Pause for a moment at the top, then slowly lower your heels back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैर की उंगलियों को किसी ऊंची सतह, जैसे सीढ़ी या ब्लॉक पर रखकर खड़े हो जाएं।","संतुलन के लिए अपने हाथों को दीवार या रेलिंग जैसे किसी स्थिर सहारे पर रखें।","अपनी एड़ियों को जितना संभव हो उतना ऊपर उठाएं, अपने शरीर का वजन अपने पैरों की उंगलियों पर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी एड़ियों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1275', 'Drop Push Up', 'chest', 'pectorals', '["triceps","shoulders"]', 'body weight', 'strength', NULL, '["Start in a high plank position with your hands slightly wider than shoulder-width apart.","Lower your chest towards the ground, keeping your elbows close to your body.","Once your chest is just above the ground, quickly drop your knees to the ground.","Push yourself back up to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["अपने हाथों को कंधे की चौड़ाई से थोड़ा चौड़ा रखते हुए एक ऊंचे तख़्ते की स्थिति से शुरुआत करें।","अपनी कोहनियों को अपने शरीर के पास रखते हुए, अपनी छाती को ज़मीन की ओर झुकाएँ।","एक बार जब आपकी छाती जमीन से ऊपर हो जाए, तो जल्दी से अपने घुटनों को जमीन पर टिका दें।","अपनी भुजाओं को फैलाकर अपने आप को प्रारंभिक स्थिति में वापस धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0285', 'Dumbbell Alternate Biceps Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'beginner', '["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions, alternating arms."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आगे की ओर हों और बाहें पूरी तरह फैली हुई हों।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ, बारी-बारी से हथियार।"]', '["Dumbbell_Alternate_Bicep_Curl/0.jpg","Dumbbell_Alternate_Bicep_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-2403', 'Dumbbell Alternate Biceps Curl (With Arm Blaster)', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Place the arm blaster on your upper arms, ensuring a secure fit.","Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with the opposite arm.","Continue alternating arms for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर सीधे खड़े हो जाएं और दोनों हाथों में डंबल पकड़ लें, हथेलियां आगे की ओर हों।","सुरक्षित फिट सुनिश्चित करते हुए, आर्म ब्लास्टर को अपनी ऊपरी बांहों पर रखें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए एक डम्बल को अपने कंधे की ओर मोड़ें।","डंबल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","विपरीत भुजा से भी यही क्रिया दोहराएँ।","दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1646', 'Dumbbell Alternate Hammer Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'beginner', '["Sit on a preacher bench with a dumbbell in each hand, palms facing your torso and arms fully extended.","Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर एक उपदेशक बेंच पर बैठें, हथेलियाँ आपके धड़ की ओर हों और भुजाएँ पूरी तरह फैली हुई हों।","अपनी ऊपरी भुजाओं को स्थिर रखें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ते हुए सांस छोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की अनुशंसित मात्रा के लिए दोहराएँ।"]', '["Preacher_Hammer_Dumbbell_Curl/0.jpg","Preacher_Hammer_Dumbbell_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1647', 'Dumbbell Alternate Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a preacher bench with a dumbbell in each hand, palms facing up.","Rest your upper arms on the pad of the preacher bench, allowing your arms to fully extend.","Keeping your upper arms stationary, exhale and curl the dumbbell in your right hand as you contract your biceps.","Continue to curl the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Pause for a moment, then inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with your left arm.","Continue alternating arms for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ ऊपर की ओर रखते हुए, उपदेशक बेंच पर बैठें।","अपनी ऊपरी भुजाओं को उपदेशक बेंच के पैड पर रखें, जिससे आपकी भुजाओं को पूरी तरह फैलने का मौका मिले।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए अपने दाहिने हाथ में डंबल को मोड़ें।","डंबल को तब तक मोड़ना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाए।","एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डंबल को वापस शुरुआती स्थिति में ले आएं।","अपने बाएं हाथ से इस क्रिया को दोहराएं।","दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1648', 'Dumbbell Alternate Seated Hammer Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended down.","Keep your back straight and your elbows close to your torso.","Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Pause for a brief moment, then inhale and slowly lower the dumbbell back to the starting position.","Repeat the movement with your left arm.","Continue alternating arms for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर एक बेंच पर बैठें, हथेलियाँ आपके धड़ की ओर हों और भुजाएँ नीचे की ओर फैली हुई हों।","अपनी पीठ सीधी रखें और अपनी कोहनियाँ अपने धड़ के पास रखें।","साँस छोड़ें और अपने दाहिने हाथ में डम्बल को अपने कंधे की ओर मोड़ें, अपनी ऊपरी भुजा को स्थिर रखें।","डंबल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाए।","थोड़ी देर रुकें, फिर सांस लें और धीरे-धीरे डंबल को वापस शुरुआती स्थिति में ले आएं।","अपने बाएं हाथ से इस क्रिया को दोहराएं।","दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0286', 'Dumbbell Alternate Side Press', 'shoulders', 'delts', '["triceps","core"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height.","Press one dumbbell overhead while keeping the other dumbbell at shoulder height.","Lower the pressed dumbbell back to shoulder height while pressing the other dumbbell overhead.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में कंधे की ऊंचाई पर डंबल पकड़ें।","एक डम्बल को ऊपर की ओर दबाएँ जबकि दूसरे डम्बल को कंधे की ऊँचाई पर रखें।","दूसरे डम्बल को ऊपर की ओर दबाते हुए दबाए गए डम्बल को वापस कंधे की ऊँचाई तक नीचे लाएँ।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1649', 'Dumbbell Alternating Bicep Curl With Leg Raised On Exercise Ball', 'upper arms', 'biceps', '["forearms","shoulders"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Place an exercise ball behind you and position one foot on top of it, keeping your balance.","With your arms fully extended and elbows close to your sides, curl one dumbbell towards your shoulder while keeping your upper arm stationary.","Lower the dumbbell back down to the starting position and repeat with the other arm.","Continue alternating arms for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों में डंबल पकड़ लें, हथेलियां आगे की ओर हों।","अपने पीछे एक व्यायाम गेंद रखें और अपना संतुलन बनाए रखते हुए एक पैर उसके ऊपर रखें।","अपनी भुजाओं को पूरी तरह फैलाकर और कोहनियों को अपनी भुजाओं के पास रखते हुए, अपनी ऊपरी भुजा को स्थिर रखते हुए एक डम्बल को अपने कंधे की ओर मोड़ें।","डम्बल को वापस प्रारंभिक स्थिति में लाएँ और दूसरे हाथ से दोहराएँ।","दोहराव की वांछित संख्या के लिए भुजाओं को बारी-बारी से जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1650', 'Dumbbell Alternating Seated Bicep Curl On Exercise Ball', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Keeping your upper arms stationary, exhale and curl one dumbbell while rotating your forearm until your palm is facing your shoulder.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat the curl with the other arm.","Continue alternating curls for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक व्यायाम बॉल पर बैठें।","अपनी हथेलियों को आगे की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपनी बांह को घुमाते हुए एक डंबल को मोड़ें जब तक कि आपकी हथेली आपके कंधे की ओर न आ जाए।","श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","दूसरे हाथ से भी कर्ल दोहराएं।","दोहराव की वांछित संख्या के लिए बारी-बारी से कर्ल जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2137', 'Dumbbell Arnold Press', 'shoulders', 'delts', '["triceps","upper chest"]', 'dumbbell', 'strength', 'intermediate', '["Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Press the dumbbells upward until your arms are fully extended and your palms are facing forward.","Rotate your wrists as you lift, so that your palms are facing forward at the top of the movement.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["पीठ के सहारे एक बेंच पर बैठें और प्रत्येक हाथ में कंधे के स्तर पर डम्बल पकड़ें, हथेलियाँ आपके शरीर की ओर हों और कोहनियाँ मुड़ी हुई हों।","डम्बल को ऊपर की ओर तब तक दबाएँ जब तक आपकी भुजाएँ पूरी तरह विस्तारित न हो जाएँ और आपकी हथेलियाँ आगे की ओर न आ जाएँ।","उठाते समय अपनी कलाइयों को घुमाएँ, ताकि आपकी हथेलियाँ गति के शीर्ष पर आगे की ओर हों।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Arnold_Dumbbell_Press/0.jpg","Arnold_Dumbbell_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0287', 'Dumbbell Arnold Press v. 2', 'shoulders', 'delts', '["triceps","upper chest"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with back support and hold a dumbbell in each hand at shoulder level, palms facing your body and elbows bent.","Press the dumbbells upward until your arms are fully extended and your palms are facing forward.","Rotate your wrists as you lift, so that your palms end up facing forward at the top of the movement.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["पीठ के सहारे एक बेंच पर बैठें और प्रत्येक हाथ में कंधे के स्तर पर डम्बल पकड़ें, हथेलियाँ आपके शरीर की ओर हों और कोहनियाँ मुड़ी हुई हों।","डम्बल को ऊपर की ओर तब तक दबाएँ जब तक आपकी भुजाएँ पूरी तरह विस्तारित न हो जाएँ और आपकी हथेलियाँ आगे की ओर न आ जाएँ।","उठाते समय अपनी कलाइयों को घुमाएँ, ताकि आपकी हथेलियाँ गति के शीर्ष पर आगे की ओर रहें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0288', 'Dumbbell Around Pullover', 'chest', 'pectorals', '["triceps","latissimus dorsi"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with your head at one end and your feet firmly on the ground.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping your arms straight, slowly lower the dumbbell behind your head in an arc motion.","Pause for a moment at the bottom, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपने सिर को एक छोर पर रखकर और अपने पैरों को जमीन पर मजबूती से रखकर सीधे लेट जाएं।","दोनों हाथों से डम्बल पकड़ें और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी भुजाओं को सीधा रखते हुए, धीरे-धीरे डम्बल को अपने सिर के पीछे एक चाप गति में नीचे लाएँ।","नीचे एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0289', 'Dumbbell Bench Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'dumbbell', 'strength', 'beginner', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand, with your palms facing forward and your arms extended above your chest.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Pause for a moment, then push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","प्रत्येक हाथ में एक डम्बल पकड़ें, आपकी हथेलियाँ आगे की ओर हों और आपकी भुजाएँ आपकी छाती के ऊपर फैली हुई हों।","अपनी कोहनियों को 90 डिग्री के कोण पर रखते हुए, डम्बल को धीरे-धीरे अपनी छाती के किनारों तक नीचे लाएँ।","एक पल के लिए रुकें, फिर अपनी बाहों को पूरी तरह फैलाते हुए डम्बल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Dumbbell_Bench_Press/0.jpg","Dumbbell_Bench_Press/1.jpg"]', 5, 'sets', 1, 'opengym', 1),
('og-0290', 'Dumbbell Bench Seated Press', 'shoulders', 'delts', '["triceps","chest"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with a dumbbell in each hand, resting on your thighs.","Lean back and position the dumbbells to the sides of your chest, palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर अपनी जाँघों पर आराम करते हुए एक बेंच पर बैठें।","पीछे झुकें और डम्बल को अपनी छाती के किनारों पर रखें, हथेलियाँ आगे की ओर हों।","डम्बल को तब तक ऊपर की ओर दबाएँ जब तक आपकी भुजाएँ पूरी तरह विस्तारित न हो जाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0291', 'Dumbbell Bench Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'dumbbell', 'strength', 'intermediate', '["Place a dumbbell on the ground in front of a bench.","Stand facing away from the bench with your feet shoulder-width apart.","Bend at the knees and hips to lower yourself down towards the bench, keeping your chest up and back straight.","Once your glutes touch the bench, push through your heels to stand back up to the starting position.","Repeat for the desired number of repetitions."]', '["डंबल को बेंच के सामने जमीन पर रखें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए बेंच से दूर की ओर मुंह करके खड़े हो जाएं।","घुटनों और कूल्हों के बल झुकें और अपने आप को बेंच की ओर नीचे करें, अपनी छाती को ऊपर और पीठ को सीधा रखें।","एक बार जब आपके ग्लूट्स बेंच को छू लें, तो प्रारंभिक स्थिति में वापस खड़े होने के लिए अपनी एड़ियों को धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Dumbbell_Squat_To_A_Bench/0.jpg","Dumbbell_Squat_To_A_Bench/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0293', 'Dumbbell Bent Over Row', 'back', 'upper back', '["biceps","forearms"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in each hand with your palms facing your body.","Bend forward at the hips, keeping your back straight and your core engaged.","Let your arms hang straight down towards the floor, with your elbows slightly bent.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, घुटने थोड़े मुड़े हुए हों और अपनी हथेलियों को अपने शरीर की ओर रखते हुए प्रत्येक हाथ में डंबल पकड़ें।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, कूल्हों के बल आगे की ओर झुकें।","अपनी भुजाओं को फर्श की ओर सीधा लटका रहने दें, आपकी कोहनियाँ थोड़ी मुड़ी हुई हों।","अपने कंधे के ब्लेड को एक साथ दबाते हुए, डम्बल को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-1651', 'Dumbbell Bicep Curl Lunge With Bowling Motion', 'upper arms', 'biceps', '["forearms","shoulders"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Take a step forward with your right foot, bending your right knee and lowering your body into a lunge position.","As you lunge forward, curl the dumbbells up towards your shoulders, keeping your elbows close to your body.","At the bottom of the lunge, rotate your torso to the right, as if you were bowling a ball.","Reverse the motion, stepping back with your right foot and returning to the starting position while lowering the dumbbells back down.","Repeat the lunge and curl motion, this time rotating your torso to the left.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपनी हथेलियों को आगे की ओर रखते हुए प्रत्येक हाथ में डंबल पकड़ें।","अपने दाहिने पैर के साथ एक कदम आगे बढ़ाएं, अपने दाहिने घुटने को मोड़ें और अपने शरीर को एक लंज स्थिति में नीचे लाएं।","जैसे ही आप आगे बढ़ते हैं, अपनी कोहनियों को अपने शरीर के करीब रखते हुए, डम्बल को अपने कंधों की ओर मोड़ें।","लंज के निचले भाग में, अपने धड़ को दाईं ओर घुमाएं, जैसे कि आप गेंद फेंक रहे हों।","गति को उल्टा करें, अपने दाहिने पैर से पीछे हटें और डम्बल को वापस नीचे करते हुए प्रारंभिक स्थिति में लौट आएं।","लंज और कर्ल गति को दोहराएं, इस बार अपने धड़ को बाईं ओर घुमाएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1652', 'Dumbbell Bicep Curl On Exercise Ball With Leg Raised', 'upper arms', 'biceps', '["forearms","shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.","Slowly curl the dumbbells towards your shoulders, keeping your elbows close to your sides.","Pause for a moment at the top of the movement, then slowly lower the dumbbells back to the starting position.","While performing the bicep curl, raise one leg off the ground and hold it in the air for the duration of the exercise.","Repeat for the desired number of repetitions, then switch legs and repeat."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक व्यायाम बॉल पर बैठें।","अपनी हथेलियों को आगे की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें।","धीरे-धीरे डम्बल को अपने कंधों की ओर मोड़ें, अपनी कोहनियों को अपनी भुजाओं के पास रखें।","गति के शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","बाइसेप कर्ल करते समय, एक पैर को जमीन से ऊपर उठाएं और व्यायाम की अवधि के लिए इसे हवा में रखें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1653', 'Dumbbell Bicep Curl With Stork Stance', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.","Extend one leg behind you, balancing on the toes of that foot.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और दोनों हाथों में डंबल पकड़ लें, हथेलियां आगे की ओर हों।","अपने एक पैर को अपने पीछे फैलाएं, उस पैर की उंगलियों पर संतुलन बनाते हुए।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0294', 'Dumbbell Biceps Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'beginner', '["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आगे की ओर हों और बाहें पूरी तरह फैली हुई हों।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Dumbbell_Alternate_Bicep_Curl/0.jpg","Dumbbell_Alternate_Bicep_Curl/1.jpg"]', 5, 'sets', 1, 'opengym', 1),
('og-2401', 'Dumbbell Biceps Curl (With Arm Blaster)', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आगे की ओर हों।","अपनी कोहनियों को अपने धड़ के पास रखें और अपनी ऊपरी भुजाओं को स्थिर रखें।","सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन मोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1654', 'Dumbbell Biceps Curl Reverse', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ नीचे की ओर हों और बाहें पूरी तरह फैली हुई हों।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1655', 'Dumbbell Biceps Curl Squat', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Keeping your back straight and your elbows close to your sides, exhale and curl the dumbbells up towards your shoulders.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपनी हथेलियों को आगे की ओर रखते हुए प्रत्येक हाथ में डंबल पकड़ें।","अपनी पीठ को सीधा और अपनी कोहनियों को बगल के पास रखते हुए सांस छोड़ें और डम्बल को अपने कंधों की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1656', 'Dumbbell Biceps Curl V Sit On Bosu Ball', 'upper arms', 'biceps', '["forearms","shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on a bosu ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in each hand with your palms facing forward and your arms fully extended down by your sides.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को 90 डिग्री के कोण पर मोड़कर बोसु बॉल पर बैठें।","अपनी हथेलियों को आगे की ओर रखते हुए प्रत्येक हाथ में एक डम्बल पकड़ें और अपनी भुजाएँ पूरी तरह से अपनी तरफ नीचे की ओर फैलाएँ।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1201', 'Dumbbell Burpee', 'cardio', 'cardiovascular system', '["quadriceps","hamstrings","calves","shoulders","triceps","core"]', 'dumbbell', 'cardio', NULL, '["Start in a standing position with your feet shoulder-width apart and a dumbbell in each hand.","Lower your body into a squat position, placing the dumbbells on the ground in front of you.","Kick your feet back into a push-up position, keeping your body in a straight line.","Perform a push-up, bending your elbows and lowering your chest towards the ground.","Jump your feet back towards your hands, landing in a squat position.","Stand up explosively, lifting the dumbbells off the ground and bringing them to your shoulders.","Press the dumbbells overhead, fully extending your arms.","Lower the dumbbells back to your shoulders and repeat the entire sequence for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और प्रत्येक हाथ में डम्बल लेकर खड़े होकर शुरुआत करें।","अपने शरीर को स्क्वाट स्थिति में लाएँ, डम्बल को अपने सामने ज़मीन पर रखें।","अपने शरीर को सीधी रेखा में रखते हुए अपने पैरों को वापस पुश-अप स्थिति में लाएँ।","अपनी कोहनियों को मोड़ते हुए और अपनी छाती को ज़मीन की ओर झुकाते हुए पुश-अप करें।","स्क्वाट स्थिति में उतरते हुए, अपने पैरों को अपने हाथों की ओर वापस उछालें।","डम्बल को जमीन से उठाकर अपने कंधों तक लाते हुए विस्फोटक तरीके से खड़े हो जाएं।","अपनी बाहों को पूरी तरह फैलाते हुए डम्बल को ऊपर की ओर दबाएं।","डम्बल को वापस अपने कंधों पर लाएँ और वांछित संख्या में दोहराव के लिए पूरे क्रम को दोहराएँ।"]', NULL, 8, 'time', 0, 'opengym', 1),
('og-0295', 'Dumbbell Clean', 'upper legs', 'glutes', '["hamstrings","quadriceps","calves"]', 'dumbbell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.","Explosively extend your hips and knees, driving through your heels to jump off the ground.","As you jump, shrug your shoulders and pull the dumbbells up towards your shoulders, keeping them close to your body.","Catch the dumbbells at shoulder height, with your elbows pointing forward and your palms facing up.","Lower the dumbbells back down to the starting position by reversing the movement.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डंबल को ओवरहैंड पकड़ के साथ पकड़ें।","अपने घुटनों को मोड़ें और अपने कूल्हों को स्क्वाट स्थिति में लाएं, अपनी पीठ सीधी और छाती ऊपर रखें।","जमीन से कूदने के लिए अपनी एड़ियों के माध्यम से गाड़ी चलाते हुए अपने कूल्हों और घुटनों को तेजी से बढ़ाएं।","जैसे ही आप कूदते हैं, अपने कंधों को सिकोड़ें और डम्बल को अपने कंधों की ओर खींचें, उन्हें अपने शरीर के करीब रखें।","डम्बल को कंधे की ऊंचाई पर पकड़ें, आपकी कोहनियाँ आगे की ओर हों और आपकी हथेलियाँ ऊपर की ओर हों।","गति को उलट कर डम्बल को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Dumbbell_Clean/0.jpg","Dumbbell_Clean/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1731', 'Dumbbell Close Grip Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'dumbbell', 'strength', 'beginner', '["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.","Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.","As you exhale, use your triceps to lift the dumbbells back to the starting position. Make sure to use only your triceps and do not use your forearms or biceps to help lift the dumbbells.","After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर अपनी जांघों पर आराम करते हुए एक सपाट बेंच पर बैठें।","डम्बल उठाने में मदद के लिए अपनी जांघों का उपयोग करते हुए, डम्बल को एक-एक करके उठाएं ताकि आप उन्हें कंधे की चौड़ाई पर अपने सामने पकड़ सकें।","एक बार कंधे की चौड़ाई पर, अपनी कलाइयों को आगे की ओर घुमाएँ ताकि आपके हाथों की हथेलियाँ आपसे दूर की ओर हों। यह आपकी प्रारंभिक स्थिति होगी.","जैसे ही आप सांस लेते हैं, धीरे-धीरे डम्बल को अपनी तरफ नीचे करें जब तक कि वे आपकी छाती के बराबर न हो जाएं।","जैसे ही आप साँस छोड़ते हैं, डम्बल को प्रारंभिक स्थिति में वापस उठाने के लिए अपने ट्राइसेप्स का उपयोग करें। सुनिश्चित करें कि आप केवल अपने ट्राइसेप्स का उपयोग करें और डम्बल उठाने में मदद के लिए अपने फोरआर्म्स या बाइसेप्स का उपयोग न करें।","अनुबंधित स्थिति में दूसरे विराम के बाद, निर्धारित मात्रा में दोहराव के लिए आंदोलन को दोहराएं।"]', '["Close-Grip_Dumbbell_Press/0.jpg","Close-Grip_Dumbbell_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0296', 'Dumbbell Close-Grip Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'dumbbell', 'strength', 'beginner', '["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.","Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.","As you exhale, use your triceps to lift the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर अपनी जांघों पर आराम करते हुए एक सपाट बेंच पर बैठें।","डम्बल उठाने में मदद के लिए अपनी जांघों का उपयोग करते हुए, डम्बल को एक-एक करके उठाएं ताकि आप उन्हें कंधे की चौड़ाई पर अपने सामने पकड़ सकें।","एक बार कंधे की चौड़ाई पर, अपनी कलाइयों को आगे की ओर घुमाएँ ताकि आपके हाथों की हथेलियाँ आपसे दूर की ओर हों। यह आपकी प्रारंभिक स्थिति होगी.","जैसे ही आप सांस लेते हैं, धीरे-धीरे डम्बल को अपनी तरफ नीचे करें जब तक कि वे आपकी छाती के बराबर न हो जाएं।","जैसे ही आप साँस छोड़ते हैं, डम्बल को प्रारंभिक स्थिति में वापस उठाने के लिए अपने ट्राइसेप्स का उपयोग करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Close-Grip_Dumbbell_Press/0.jpg","Close-Grip_Dumbbell_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0297', 'Dumbbell Concentration Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your legs spread apart and a dumbbell in one hand, resting your elbow on the inside of your thigh.","Fully extend your arm and hold the dumbbell with an underhand grip.","Keeping your upper arm stationary, exhale and curl the weight up towards your shoulder while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को फैलाकर और एक हाथ में डम्बल लेकर, अपनी कोहनी को अपनी जांघ के अंदर पर टिकाकर एक बेंच पर बैठें।","अपनी बांह को पूरी तरह फैलाएं और डंबल को हाथ से पकड़ें।","अपनी ऊपरी भुजा को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को अपने कंधे की ओर मोड़ें।","डंबल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3635', 'Dumbbell Contralateral Forward Lunge', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, keeping your back straight and core engaged.","Lower your body by bending both knees until your right thigh is parallel to the ground.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Alternate legs for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डम्बल पकड़ें।","अपने दाहिने पैर के साथ एक कदम आगे बढ़ाएं, अपनी पीठ को सीधा और मुख्य भाग को व्यस्त रखें।","दोनों घुटनों को मोड़कर अपने शरीर को नीचे करें जब तक कि आपकी दाहिनी जांघ जमीन के समानांतर न हो जाए।","प्रारंभिक स्थिति में लौटने के लिए अपनी दाहिनी एड़ी को धक्का दें।","अपने बाएँ पैर से दोहराएँ।","दोहराव की वांछित संख्या के लिए पैरों को वैकल्पिक करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0298', 'Dumbbell Cross Body Hammer Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the dumbbells across your body towards your opposite shoulder.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आपके शरीर की ओर हों।","अपनी कोहनियों को अपने धड़ के पास रखें और अपनी ऊपरी भुजाओं को स्थिर रखें।","साँस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें, डम्बल को अपने शरीर के पार अपने विपरीत कंधे की ओर लाएँ।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1657', 'Dumbbell Cross Body Hammer Curl v. 2', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing your body.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps, bringing the dumbbells as close to your opposite shoulder as possible.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आपके शरीर की ओर हों।","अपनी कोहनियों को अपने धड़ के पास रखें और अपनी ऊपरी भुजाओं को स्थिर रखें।","सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें, डम्बल को जितना संभव हो सके अपने विपरीत कंधे के करीब लाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0299', 'Dumbbell Cuban Press', 'shoulders', 'delts', '["triceps","upper back"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.","Keeping your core engaged and your elbows slightly bent, press the dumbbells up and overhead until your arms are fully extended.","Rotate your wrists so that your palms are facing forward.","Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as you do so.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपनी हथेलियों को नीचे की ओर रखते हुए प्रत्येक हाथ में कंधे की ऊंचाई पर डंबल पकड़ें।","अपने कोर को व्यस्त रखते हुए और अपनी कोहनियों को थोड़ा मोड़कर, डम्बल को ऊपर और ऊपर की ओर तब तक दबाएं जब तक कि आपकी बाहें पूरी तरह से विस्तारित न हो जाएं।","अपनी कलाइयों को इस प्रकार घुमाएँ कि आपकी हथेलियाँ आगे की ओर हों।","धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ, ऐसा करते समय अपनी कलाइयों को वापस प्रारंभिक स्थिति में घुमाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2136', 'Dumbbell Cuban Press v. 2', 'shoulders', 'delts', '["triceps","upper back"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing down.","Keeping your core engaged and your back straight, press the dumbbells straight up overhead until your arms are fully extended.","Rotate your wrists so that your palms are facing forward.","Lower the dumbbells back down to shoulder height, rotating your wrists back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपनी हथेलियों को नीचे की ओर रखते हुए प्रत्येक हाथ में कंधे की ऊंचाई पर डंबल पकड़ें।","अपने कोर को व्यस्त रखते हुए और अपनी पीठ को सीधा रखते हुए, डम्बल को सीधे ऊपर की ओर दबाएं जब तक कि आपकी बाहें पूरी तरह से विस्तारित न हो जाएं।","अपनी कलाइयों को इस प्रकार घुमाएँ कि आपकी हथेलियाँ आगे की ओर हों।","डम्बल को वापस कंधे की ऊँचाई तक नीचे लाएँ, अपनी कलाइयों को वापस प्रारंभिक स्थिति में घुमाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0300', 'Dumbbell Deadlift', 'upper legs', 'glutes', '["hamstrings","lower back"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, toes pointing forward.","Hold a dumbbell in each hand, palms facing your body, arms extended downwards.","Bend at your hips and knees, lowering the dumbbells towards the ground while keeping your back straight.","Push through your heels and extend your hips and knees, lifting the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, पैर की उंगलियां आगे की ओर हों।","प्रत्येक हाथ में एक डम्बल पकड़ें, हथेलियाँ आपके शरीर की ओर हों, भुजाएँ नीचे की ओर फैली हुई हों।","अपने कूल्हों और घुटनों को मोड़ें, अपनी पीठ को सीधा रखते हुए डम्बल को ज़मीन की ओर झुकाएँ।","अपनी एड़ियों से धक्का दें और अपने कूल्हों और घुटनों को फैलाएं, डम्बल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0301', 'Dumbbell Decline Bench Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'dumbbell', 'strength', 'beginner', '["Lie down on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["अपने पैरों को सुरक्षित रखते हुए और अपने सिर को अपने कूल्हों से नीचे करके एक डिक्लाइन बेंच पर लेट जाएँ।","प्रत्येक हाथ में एक डम्बल पकड़ें और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ, हथेलियाँ आगे की ओर हों।","अपनी कोहनियों को 90 डिग्री के कोण पर रखते हुए, डम्बल को धीरे-धीरे अपनी छाती के किनारों तक नीचे लाएँ।","अपनी भुजाओं को पूरी तरह फैलाते हुए, डम्बल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Decline_Dumbbell_Bench_Press/0.jpg","Decline_Dumbbell_Bench_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0302', 'Dumbbell Decline Fly', 'chest', 'pectorals', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Lie on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को सुरक्षित रखते हुए और अपने सिर को अपने कूल्हों से नीचे करके एक डिक्लाइन बेंच पर लेटें।","अपनी हथेलियों को एक-दूसरे के सामने रखते हुए और अपनी बाहों को अपनी छाती के ऊपर फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें।","जब तक आप अपनी छाती में खिंचाव महसूस न करें तब तक डम्बल को एक चौड़े चाप में बगल की ओर नीचे करें।","एक पल के लिए रुकें, फिर डम्बल को प्रारंभिक स्थिति में वापस लाने के लिए अपनी छाती की मांसपेशियों को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0303', 'Dumbbell Decline Hammer Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'dumbbell', 'strength', NULL, '["Lie on a decline bench with your feet secured and your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells to the sides of your chest, keeping your elbows slightly bent.","Press the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["अपने पैरों को सुरक्षित रखते हुए और अपने सिर को अपने कूल्हों से नीचे करके एक डिक्लाइन बेंच पर लेटें।","अपनी हथेलियों को एक-दूसरे के सामने रखते हुए और अपनी बाहों को अपनी छाती के ऊपर फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी कोहनियों को थोड़ा मुड़ा हुआ रखते हुए, डम्बल को अपनी छाती के किनारों तक नीचे लाएँ।","अपनी भुजाओं को पूरी तरह फैलाते हुए डम्बल को वापस प्रारंभिक स्थिति में दबाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1276', 'Dumbbell Decline One Arm Fly', 'chest', 'pectorals', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Lie down on a decline bench with a dumbbell in one hand, resting it on your thigh.","Using your thigh to help raise the dumbbell, lift it up to shoulder width with your palm facing your torso.","Rotate your wrist so that the palm of your hand is facing forward.","As you breathe in, lower the dumbbell slowly to the side until you feel a stretch in your chest.","Exhale and use your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["एक हाथ में डम्बल लेकर उसे अपनी जांघ पर टिकाकर डिक्लाइन बेंच पर लेट जाएँ।","डम्बल को उठाने में मदद के लिए अपनी जांघ का उपयोग करते हुए, अपनी हथेली को अपने धड़ की ओर रखते हुए इसे कंधे की चौड़ाई तक उठाएं।","अपनी कलाई को घुमाएं ताकि आपके हाथ की हथेली आगे की ओर रहे।","जैसे ही आप सांस अंदर लें, डंबल को धीरे-धीरे बगल की ओर नीचे करें जब तक कि आपको अपनी छाती में खिंचाव महसूस न हो।","साँस छोड़ें और डम्बल को वापस प्रारंभिक स्थिति में लाने के लिए अपनी छाती की मांसपेशियों का उपयोग करें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1617', 'Dumbbell Decline One Arm Hammer Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'dumbbell', 'strength', NULL, '["Lie on a decline bench with a dumbbell in one hand, resting on your chest.","Extend your arm straight up, keeping your elbow slightly bent.","Lower the dumbbell down towards your shoulder, keeping your elbow close to your body.","Press the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["एक हाथ में डम्बल लेकर अपनी छाती पर आराम करते हुए डिक्लाइन बेंच पर लेट जाएँ।","अपनी कोहनी को थोड़ा मुड़ा हुआ रखते हुए अपना हाथ सीधा ऊपर फैलाएँ।","अपनी कोहनी को अपने शरीर के करीब रखते हुए डम्बल को अपने कंधे की ओर नीचे करें।","डम्बल को वापस प्रारंभिक स्थिति में दबाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0305', 'Dumbbell Decline Shrug', 'back', 'traps', '["shoulders","rhomboids"]', 'dumbbell', 'strength', NULL, '["Set up a decline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting against it.","Hold a dumbbell in each hand with your arms fully extended towards the floor.","Keeping your arms straight, raise your shoulders towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["45-डिग्री के कोण पर डिक्लाइन बेंच स्थापित करें।","अपनी छाती और पेट को बेंच पर टिकाकर चेहरे के बल लेट जाएँ।","अपनी भुजाओं को फर्श की ओर पूरी तरह फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी भुजाओं को सीधा रखते हुए, अपने कंधों को अपने कानों की ओर जितना संभव हो उतना ऊपर उठाएं।","एक पल के लिए संकुचन को रोककर रखें, फिर धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0304', 'Dumbbell Decline Shrug v. 2', 'back', 'traps', '["shoulders","rhomboids"]', 'dumbbell', 'strength', NULL, '["Set up a decline bench at a 45-degree angle.","Lie face down on the bench with your chest and stomach resting on it.","Hold a dumbbell in each hand with your palms facing each other and your arms fully extended.","Keeping your arms straight, raise your shoulders as high as possible while squeezing your shoulder blades together.","Hold the contraction for a brief pause, then lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["45-डिग्री के कोण पर डिक्लाइन बेंच स्थापित करें।","अपनी छाती और पेट को उस पर टिकाकर बेंच पर मुंह करके लेट जाएं।","अपनी हथेलियों को एक-दूसरे के सामने रखते हुए और अपनी बाहों को पूरी तरह फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी बाहों को सीधा रखते हुए, अपने कंधों को एक साथ निचोड़ते हुए अपने कंधों को जितना संभव हो उतना ऊपर उठाएं।","संकुचन को थोड़ी देर के लिए रोककर रखें, फिर डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0306', 'Dumbbell Decline Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', 'beginner', '["Lie on a decline bench with your head lower than your feet and hold a dumbbell in each hand, palms facing each other.","Extend your arms fully, keeping your elbows close to your head.","Lower the dumbbells slowly behind your head, bending your elbows.","Pause for a moment, then raise the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने सिर को अपने पैरों से नीचे करके एक डिक्लाइन बेंच पर लेटें और दोनों हाथों में एक-एक डम्बल पकड़ें, हथेलियाँ एक-दूसरे के सामने हों।","अपनी कोहनियों को अपने सिर के पास रखते हुए, अपनी भुजाओं को पूरी तरह फैलाएँ।","अपनी कोहनियों को मोड़ते हुए डम्बल को धीरे-धीरे अपने सिर के पीछे नीचे लाएँ।","एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Decline_Dumbbell_Triceps_Extension/0.jpg","Decline_Dumbbell_Triceps_Extension/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0307', 'Dumbbell Decline Twist Fly', 'chest', 'pectorals', '["shoulders","triceps"]', 'dumbbell', 'strength', NULL, '["Lie down on a decline bench with your head lower than your hips.","Hold a dumbbell in each hand with your palms facing each other and your arms extended straight up over your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","As you lower the dumbbells, twist your wrists so that your palms face forward at the bottom of the movement.","Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles at the top.","Repeat for the desired number of repetitions."]', '["अपने सिर को अपने कूल्हों से नीचे करके डिक्लाइन बेंच पर लेट जाएँ।","अपनी हथेलियों को एक-दूसरे के सामने रखते हुए प्रत्येक हाथ में एक डम्बल पकड़ें और आपकी भुजाएँ सीधे आपकी छाती के ऊपर फैली हुई हों।","जब तक आप अपनी छाती में खिंचाव महसूस न करें तब तक डम्बल को एक चौड़े चाप में बगल की ओर नीचे करें।","जैसे ही आप डम्बल को नीचे करते हैं, अपनी कलाइयों को मोड़ें ताकि आपकी हथेलियाँ नीचे की ओर आगे की ओर हों।","गति को उल्टा करें और शीर्ष पर अपनी छाती की मांसपेशियों को निचोड़ते हुए डम्बल को शुरुआती स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1437', 'Dumbbell Finger Curls', 'lower arms', 'forearms', '["wrist flexors","wrist extensors"]', 'dumbbell', 'strength', NULL, '["Sit on a bench or chair with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh, palm facing up.","Allow the dumbbell to roll down to your fingertips, then curl it back up by flexing your fingers.","Repeat for the desired number of repetitions, then switch to the other hand."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपनी पीठ सीधी करके एक बेंच या कुर्सी पर बैठें।","एक हाथ में डंबल को अंडरहैंड ग्रिप से पकड़ें, अपने अग्रबाहु को अपनी जांघ पर टिकाएं, हथेली ऊपर की ओर रखें।","डम्बल को अपनी उंगलियों तक लुढ़कने दें, फिर अपनी उंगलियों को मोड़कर इसे वापस ऊपर की ओर मोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरी ओर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0308', 'Dumbbell Fly', 'chest', 'pectorals', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, with a slight bend in your elbows.","Keeping a slight bend in your elbows, lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ एक-दूसरे के सामने रखते हुए, एक बेंच पर सीधे लेट जाएँ।","अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी बाहों को अपनी छाती के ऊपर सीधा फैलाएँ।","अपनी कोहनियों को थोड़ा मोड़ते हुए, अपनी भुजाओं को एक चौड़े चाप में बगल की ओर तब तक नीचे लाएँ जब तक आपको अपनी छाती में खिंचाव महसूस न हो।","एक पल के लिए रुकें, फिर गति को उल्टा करें और डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-1277', 'Dumbbell Fly On Exercise Ball', 'chest', 'pectorals', '["shoulders","triceps"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball and hold a dumbbell in each hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported by the ball.","Extend your arms straight up above your chest, palms facing each other.","Bend your elbows slightly and lower your arms out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then reverse the movement and squeeze your chest muscles as you bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["एक व्यायाम गेंद पर बैठें और प्रत्येक हाथ में एक डम्बल पकड़ें।","अपने पैरों को आगे बढ़ाएं और अपने शरीर को तब तक नीचे घुमाएं जब तक कि आपके सिर, गर्दन और पीठ के ऊपरी हिस्से को गेंद का सहारा न मिल जाए।","अपनी बाहों को अपनी छाती के ऊपर सीधा फैलाएँ, हथेलियाँ एक-दूसरे के सामने हों।","अपनी कोहनियों को थोड़ा मोड़ें और अपनी भुजाओं को एक चौड़े चाप में बगल की ओर तब तक नीचे लाएँ जब तक आपको अपनी छाती में खिंचाव महसूस न हो।","एक पल के लिए रुकें, फिर गति को उल्टा करें और डम्बल को प्रारंभिक स्थिति में वापस लाते हुए अपनी छाती की मांसपेशियों को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1732', 'Dumbbell Forward Lunge Triceps Extension', 'upper arms', 'triceps', '["shoulders","core"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","Keep your back straight and your chest up.","Extend your arms straight overhead, keeping your elbows close to your ears.","Lower the dumbbells behind your head by bending your elbows.","Pause for a moment, then straighten your arms to return to the starting position.","Repeat the movement for the desired number of repetitions, then switch legs and repeat."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डम्बल पकड़ें।","अपने दाहिने पैर से एक कदम आगे बढ़ाएं, अपने शरीर को नीचे झुकाकर स्थिति में लाएं।","अपनी पीठ सीधी और छाती ऊपर रखें।","अपनी कोहनियों को अपने कानों के पास रखते हुए, अपनी भुजाओं को ऊपर की ओर सीधा फैलाएँ।","अपनी कोहनियों को मोड़कर डम्बल को अपने सिर के पीछे नीचे करें।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी भुजाओं को सीधा करें।","वांछित संख्या में दोहराव के लिए आंदोलन को दोहराएं, फिर पैर बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0310', 'Dumbbell Front Raise', 'shoulders', 'delts', '["biceps","trapezius"]', 'dumbbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डंबल पकड़ें और अपनी हथेलियों को अपनी जांघों की ओर रखें।","अपनी बाहों को सीधा रखते हुए, सांस छोड़ें और डम्बल को अपने सामने तब तक उठाएं जब तक वे कंधे के स्तर पर न आ जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Front_Dumbbell_Raise/0.jpg","Front_Dumbbell_Raise/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0309', 'Dumbbell Front Raise v. 2', 'shoulders', 'delts', '["trapezius","biceps"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.","Keep your back straight and engage your core.","Slowly lift the dumbbells in front of you, with your arms straight, until they are at shoulder level.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डंबल पकड़ें और अपनी हथेलियों को अपनी जांघों की ओर रखें।","अपनी पीठ सीधी रखें और अपने कोर को संलग्न रखें।","अपनी भुजाओं को सीधा रखते हुए धीरे-धीरे अपने सामने डम्बल उठाएँ, जब तक कि वे कंधे के स्तर पर न आ जाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0311', 'Dumbbell Full Can Lateral Raise', 'shoulders', 'delts', '["traps","rotator cuff"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डम्बल पकड़ें और अपनी हथेलियों को अपने शरीर की ओर रखें।","अपनी पीठ सीधी रखें और अपने कोर को संलग्न रखें।","अपनी भुजाओं को बगल की ओर उठाएं, अपनी कोहनियों को थोड़ा मोड़ते हुए, जब तक कि वे जमीन के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1760', 'Dumbbell Goblet Squat', 'upper legs', 'quads', '["glutes","hamstrings","calves"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands.","Keeping your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees.","Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.","Pause for a moment at the bottom, then push through your heels to return to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, दोनों हाथों से डंबल को अपनी छाती पर सीधा पकड़ लें।","अपनी छाती को ऊपर और कोर को व्यस्त रखते हुए, अपने कूल्हों को पीछे धकेलते हुए और अपने घुटनों को मोड़ते हुए अपने शरीर को स्क्वाट स्थिति में नीचे लाएँ।","तब तक नीचे उतरना जारी रखें जब तक कि आपकी जांघें ज़मीन के समानांतर न हो जाएं, या उतना नीचे न आ जाएं जितना आप आराम से जा सकें।","नीचे एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी एड़ियों से धक्का दें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-0313', 'Dumbbell Hammer Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आपके धड़ की ओर हों।","अपनी कोहनियों को अपने धड़ के पास रखें और अपने हाथों की हथेलियों को तब तक घुमाएँ जब तक वे आगे की ओर न आ जाएँ।","यह आपकी प्रारंभिक स्थिति होगी.","अब, ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","फिर, सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की अनुशंसित मात्रा के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-1659', 'Dumbbell Hammer Curl On Exercise Ball', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक व्यायाम बॉल पर बैठें।","अपनी हथेलियों को अपने शरीर की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए डम्बल को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0312', 'Dumbbell Hammer Curl v. 2', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आपके धड़ की ओर हों।","अपनी कोहनियों को अपने धड़ के पास रखें और अपने हाथों की हथेलियों को तब तक घुमाएँ जब तक वे आगे की ओर न आ जाएँ।","यह आपकी प्रारंभिक स्थिति होगी.","अब, ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","फिर, सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की अनुशंसित मात्रा के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2402', 'Dumbbell Hammer Curls (With Arm Blaster)', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, while holding your upper arm stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आपके धड़ की ओर हों।","अपनी कोहनियों को अपने धड़ के पास रखें और अपने हाथों की हथेलियों को तब तक घुमाएँ जब तक वे आगे की ओर न आ जाएँ।","यह आपकी प्रारंभिक स्थिति होगी.","अब, अपनी ऊपरी बांह को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","फिर, सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की अनुशंसित मात्रा के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1664', 'Dumbbell High Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing forward.","Keep your upper arms stationary and curl the dumbbells as high as possible while contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आगे की ओर हों।","अपनी ऊपरी भुजाओं को स्थिर रखें और अपने बाइसेप्स को सिकोड़ते हुए डम्बल को जितना संभव हो उतना ऊपर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3545', 'Dumbbell Incline Alternate Press', 'chest', 'pectorals', '["shoulders","triceps"]', 'dumbbell', 'strength', 'beginner', '["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Lean back on the bench and use your thighs to help raise the dumbbells to shoulder height, palms facing forward.","Once at shoulder height, rotate your wrists so that the palms of your hands are facing forward.","Push the dumbbells up with your chest and shoulders, extending your arms fully.","Lower the dumbbells back down to the starting position, keeping your elbows slightly bent.","Repeat for the desired number of repetitions, alternating arms."]', '["प्रत्येक हाथ में डम्बल लेकर अपनी जाँघों पर आराम करते हुए एक झुकी हुई बेंच पर बैठें।","बेंच पर पीछे झुकें और डम्बल को कंधे की ऊंचाई तक उठाने में मदद करने के लिए अपनी जांघों का उपयोग करें, हथेलियाँ आगे की ओर हों।","एक बार कंधे की ऊंचाई पर, अपनी कलाइयों को घुमाएं ताकि आपके हाथों की हथेलियां आगे की ओर हों।","अपनी बाहों को पूरी तरह फैलाते हुए डम्बल को अपनी छाती और कंधों से ऊपर की ओर धकेलें।","अपनी कोहनियों को थोड़ा मुड़ा हुआ रखते हुए, डम्बल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ, बारी-बारी से हथियार।"]', '["Incline_Dumbbell_Press/0.jpg","Incline_Dumbbell_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0314', 'Dumbbell Incline Bench Press', 'chest', 'pectorals', '["shoulders","triceps"]', 'dumbbell', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your feet flat on the ground and your back pressed firmly against the bench.","Hold a dumbbell in each hand, palms facing forward, and lift them to shoulder height.","Slowly lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.","Push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","बेंच पर अपने पैरों को ज़मीन पर सपाट करके बैठें और आपकी पीठ बेंच से मजबूती से चिपकी हुई हो।","प्रत्येक हाथ में डम्बल पकड़ें, हथेलियाँ आगे की ओर हों और उन्हें कंधे की ऊँचाई तक उठाएँ।","अपनी कोहनियों को 90 डिग्री के कोण पर रखते हुए धीरे-धीरे डम्बल को अपनी छाती के किनारों तक नीचे लाएँ।","अपनी भुजाओं को पूरी तरह फैलाते हुए, डम्बल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-0315', 'Dumbbell Incline Biceps Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on an incline bench with a dumbbell in each hand, palms facing forward, and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ आगे की ओर और भुजाएँ पूरी तरह फैलाकर एक झुकी हुई बेंच पर बैठें।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0316', 'Dumbbell Incline Breeding', 'chest', 'pectorals', '["shoulders","triceps"]', 'dumbbell', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing forward.","Start with your arms fully extended, perpendicular to the ground.","Lower the dumbbells slowly to the sides of your chest, keeping your elbows at a 90-degree angle.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","बेंच पर अपनी पीठ पैड से सटाकर और पैरों को ज़मीन पर सपाट करके बैठें।","प्रत्येक हाथ में एक डम्बल को ओवरहैंड पकड़ के साथ पकड़ें, हथेलियाँ आगे की ओर हों।","अपनी भुजाओं को ज़मीन से सीधा फैलाकर शुरुआत करें।","अपनी कोहनियों को 90 डिग्री के कोण पर रखते हुए, डम्बल को धीरे-धीरे अपनी छाती के किनारों तक नीचे लाएँ।","नीचे एक क्षण के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0318', 'Dumbbell Incline Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'beginner', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing forward.","Rest your upper arms on the incline bench and let your elbows hang down, fully extending your arms.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["एक झुकी हुई बेंच को 45 डिग्री के कोण पर सेट करें और उस पर दोनों हाथों में डम्बल लेकर बैठें, हथेलियाँ आगे की ओर हों।","अपनी ऊपरी भुजाओं को झुकी हुई बेंच पर टिकाएं और अपनी कोहनियों को नीचे की ओर लटका दें, अपनी भुजाओं को पूरी तरह फैला लें।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Alternate_Incline_Dumbbell_Curl/0.jpg","Alternate_Incline_Dumbbell_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0317', 'Dumbbell Incline Curl v. 2', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on an incline bench with a dumbbell in each hand, palms facing forward and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर एक झुकी हुई बेंच पर बैठें, हथेलियाँ आगे की ओर हों और बाहें पूरी तरह फैली हुई हों।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0319', 'Dumbbell Incline Fly', 'chest', 'pectorals', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Set an incline bench to a 45-degree angle.","Sit on the bench with a dumbbell in each hand, palms facing each other.","Lie back on the bench and press the dumbbells up to the starting position, directly above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', '["एक झुकी हुई बेंच को 45-डिग्री के कोण पर सेट करें।","प्रत्येक हाथ में डम्बल लेकर बेंच पर बैठें, हथेलियाँ एक-दूसरे के सामने हों।","बेंच पर पीठ के बल लेट जाएँ और डम्बल को सीधे अपनी छाती के ऊपर प्रारंभिक स्थिति में दबाएँ।","जब तक आप अपनी छाती में खिंचाव महसूस न करें तब तक डम्बल को एक चौड़े चाप में बगल की ओर नीचे करें।","एक पल के लिए रुकें, फिर डम्बल को शुरुआती स्थिति में वापस लाने के लिए अपनी छाती की मांसपेशियों को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1278', 'Dumbbell Incline Fly On Exercise Ball', 'chest', 'pectorals', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Sit on an exercise ball and roll forward until your upper back is resting on the incline bench.","Hold a dumbbell in each hand with your palms facing each other and your arms extended above your chest.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","Pause for a moment, then squeeze your chest muscles to bring the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","एक एक्सरसाइज बॉल पर बैठें और आगे की ओर तब तक रोल करें जब तक आपकी पीठ का ऊपरी हिस्सा झुकी हुई बेंच पर न टिक जाए।","अपनी हथेलियों को एक-दूसरे के सामने रखते हुए और अपनी बाहों को अपनी छाती के ऊपर फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें।","जब तक आप अपनी छाती में खिंचाव महसूस न करें तब तक डम्बल को एक चौड़े चाप में बगल की ओर नीचे करें।","एक पल के लिए रुकें, फिर डम्बल को प्रारंभिक स्थिति में वापस लाने के लिए अपनी छाती की मांसपेशियों को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0320', 'Dumbbell Incline Hammer Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on an incline bench with a dumbbell in each hand, palms facing your torso and arms fully extended.","Keep your back against the bench and your feet flat on the floor.","While keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर एक झुकी हुई बेंच पर बैठें, हथेलियाँ आपके धड़ की ओर हों और भुजाएँ पूरी तरह फैली हुई हों।","अपनी पीठ को बेंच के सामने रखें और अपने पैरों को फर्श पर सपाट रखें।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0321', 'Dumbbell Incline Hammer Press', 'chest', 'pectorals', '["shoulders","triceps"]', 'dumbbell', 'strength', NULL, '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, resting on your thighs.","Lie back on the bench and position the dumbbells at shoulder level with your palms facing each other.","Press the dumbbells up and away from your body until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक झुकी हुई बेंच को 45 डिग्री के कोण पर सेट करें और अपनी जांघों पर आराम करते हुए प्रत्येक हाथ में डंबल लेकर उस पर बैठें।","बेंच पर पीठ के बल लेट जाएं और अपनी हथेलियों को एक-दूसरे के सामने रखते हुए डम्बल को कंधे के स्तर पर रखें।","डम्बल को अपने शरीर से ऊपर और दूर तब तक दबाएँ जब तक आपकी बाहें पूरी तरह विस्तारित न हो जाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1618', 'Dumbbell Incline Hammer Press On Exercise Ball', 'upper arms', 'triceps', '["chest","shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Walk your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.","Press the dumbbells up and slightly inward, keeping your palms facing each other.","Extend your arms fully, squeezing your triceps at the top of the movement.","Slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर व्यायाम गेंद पर बैठें, हथेलियाँ एक-दूसरे के सामने हों।","अपने पैरों को आगे बढ़ाएं और अपने शरीर को गेंद के नीचे तब तक घुमाएं जब तक कि आपका सिर, गर्दन और पीठ का ऊपरी हिस्सा गेंद पर समर्थित न हो जाए।","डम्बल को कंधे के स्तर पर पकड़ें, कोहनियाँ मुड़ी हुई और किनारों की ओर इशारा करती हुई।","अपनी हथेलियों को एक-दूसरे के सामने रखते हुए डम्बल को ऊपर और थोड़ा अंदर की ओर दबाएं।","अपनी भुजाओं को पूरी तरह फैलाएँ, अपने ट्राइसेप्स को गति के शीर्ष पर दबाएँ।","धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0322', 'Dumbbell Incline Inner Biceps Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on an incline bench with a dumbbell in each hand, palms facing each other.","Rest your upper arms on the bench, allowing your elbows to hang down and your palms to face forward.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ एक-दूसरे के सामने रखते हुए, झुकी हुई बेंच पर बैठें।","अपनी ऊपरी भुजाओं को बेंच पर टिकाएं, जिससे आपकी कोहनियां नीचे लटक जाएं और आपकी हथेलियां आगे की ओर रहें।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1279', 'Dumbbell Incline One Arm Fly', 'chest', 'pectorals', '["deltoids","triceps"]', 'dumbbell', 'strength', NULL, '["Adjust the incline bench to a 30-45 degree angle.","Sit on the bench with a dumbbell in one hand, resting it on your thigh.","Lie back on the bench, keeping your feet flat on the ground.","Hold the dumbbell with your arm extended straight up over your chest.","Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.","Pause when your arm is parallel to the ground, then reverse the motion to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["इनक्लाइन बेंच को 30-45 डिग्री के कोण पर समायोजित करें।","एक हाथ में डम्बल लेकर उसे अपनी जांघ पर टिकाकर बेंच पर बैठें।","अपने पैरों को ज़मीन पर सपाट रखते हुए, बेंच पर पीठ के बल लेट जाएँ।","अपने हाथ को सीधे अपनी छाती के ऊपर फैलाकर डम्बल को पकड़ें।","अपनी कोहनी को थोड़ा मोड़ते हुए, डम्बल को एक चौड़े चाप में बगल की ओर नीचे करें।","जब आपकी भुजा ज़मीन के समानांतर हो तो रुकें, फिर डम्बल को प्रारंभिक स्थिति में वापस लाने के लिए गति को उल्टा करें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1280', 'Dumbbell Incline One Arm Fly On Exercise Ball', 'chest', 'pectorals', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with a dumbbell in one hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with your arm extended straight up over your chest, palm facing inwards.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment when your arm is parallel to the ground.","Engage your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["एक हाथ में डम्बल लेकर एक्सरसाइज बॉल पर बैठें।","अपने पैरों को आगे बढ़ाएं और अपने शरीर को तब तक नीचे घुमाएं जब तक कि आपका सिर, गर्दन और ऊपरी पीठ गेंद पर समर्थित न हो जाए।","अपनी बांह को सीधे अपनी छाती के ऊपर फैलाकर, हथेली अंदर की ओर रखते हुए डम्बल को पकड़ें।","अपनी कोहनी को थोड़ा मोड़ते हुए धीरे-धीरे डम्बल को बगल की ओर नीचे करें।","जब आपकी बांह ज़मीन के समानांतर हो तो एक क्षण रुकें।","डम्बल को शुरुआती स्थिति में वापस लाने के लिए अपनी छाती की मांसपेशियों को शामिल करें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1619', 'Dumbbell Incline One Arm Hammer Press', 'upper arms', 'triceps', '["shoulders","chest"]', 'dumbbell', 'strength', NULL, '["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.","Lean back on the bench and use your thigh to help raise the dumbbell to shoulder height.","Rotate your wrist so that your palm is facing inward, towards your body.","Press the dumbbell up and away from your body, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["एक हाथ में डम्बल लेकर अपनी जांघ पर आराम करते हुए एक झुकी हुई बेंच पर बैठें।","बेंच पर पीछे झुकें और डम्बल को कंधे की ऊंचाई तक उठाने में मदद के लिए अपनी जांघ का उपयोग करें।","अपनी कलाई को इस प्रकार घुमाएँ कि आपकी हथेली अंदर की ओर, आपके शरीर की ओर रहे।","अपनी बांह को पूरी तरह फैलाते हुए डम्बल को अपने शरीर से ऊपर और दूर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1620', 'Dumbbell Incline One Arm Hammer Press On Exercise Ball', 'upper arms', 'triceps', '["shoulders","chest"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with a dumbbell in one hand.","Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with your palm facing inward and your elbow bent at a 90-degree angle.","Press the dumbbell up towards the ceiling, straightening your arm.","Lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["एक हाथ में डम्बल लेकर एक्सरसाइज बॉल पर बैठें।","अपने पैरों को आगे बढ़ाएं और अपने शरीर को तब तक नीचे घुमाएं जब तक कि आपका सिर, गर्दन और ऊपरी पीठ गेंद पर समर्थित न हो जाए।","अपनी हथेली को अंदर की ओर रखते हुए और अपनी कोहनी को 90 डिग्री के कोण पर मोड़कर डम्बल को पकड़ें।","अपनी बांह को सीधा करते हुए डम्बल को छत की ओर दबाएं।","डम्बल को वापस प्रारंभिक स्थिति में नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0323', 'Dumbbell Incline One Arm Lateral Raise', 'shoulders', 'delts', '["trapezius","triceps"]', 'dumbbell', 'strength', NULL, '["Sit on an incline bench with a dumbbell in one hand, resting it on your thigh.","Lean forward and position your upper arm against the inside of your thigh.","Raise the dumbbell to the side, keeping your arm slightly bent and your palm facing down.","Continue lifting until your arm is parallel to the floor.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["एक हाथ में डम्बल लेकर उसे अपनी जांघ पर टिकाकर झुकी हुई बेंच पर बैठें।","आगे झुकें और अपनी ऊपरी भुजा को अपनी जांघ के अंदर की ओर रखें।","अपनी बांह को थोड़ा झुकाकर और अपनी हथेली को नीचे की ओर रखते हुए डम्बल को बगल की ओर उठाएं।","तब तक उठाना जारी रखें जब तक आपकी बांह फर्श के समानांतर न हो जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1281', 'Dumbbell Incline One Arm Press', 'chest', 'pectorals', '["shoulders","triceps"]', 'dumbbell', 'strength', NULL, '["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.","Lie back on the bench and position the dumbbell at shoulder level, palm facing forward.","Press the dumbbell upward and slightly inward, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["एक हाथ में डम्बल लेकर अपनी जांघ पर आराम करते हुए एक झुकी हुई बेंच पर बैठें।","बेंच पर पीठ के बल लेट जाएं और डंबल को कंधे के स्तर पर रखें, हथेली आगे की ओर हो।","अपनी बांह को पूरी तरह फैलाते हुए डंबल को ऊपर और थोड़ा अंदर की ओर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1282', 'Dumbbell Incline One Arm Press On Exercise Ball', 'chest', 'pectorals', '["shoulders","triceps"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with a dumbbell in one hand, feet flat on the ground.","Slowly walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbell at shoulder height with your palm facing forward.","Press the dumbbell upward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["एक हाथ में डम्बल लेकर व्यायाम बॉल पर बैठें, पैर ज़मीन पर सपाट हों।","धीरे-धीरे अपने पैरों को आगे बढ़ाएं, गेंद को तब तक घुमाएं जब तक कि आपका सिर, गर्दन और पीठ का ऊपरी हिस्सा गेंद पर समर्थित न हो जाए।","अपनी हथेली को आगे की ओर रखते हुए डम्बल को कंधे की ऊंचाई पर पकड़ें।","डम्बल को तब तक ऊपर की ओर दबाएँ जब तक आपका हाथ पूरी तरह फैल न जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0324', 'Dumbbell Incline Palm-In Press', 'chest', 'pectorals', '["shoulders","triceps"]', 'dumbbell', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Sit on the bench with a dumbbell in each hand, palms facing each other.","Plant your feet firmly on the ground and keep your back straight against the bench.","Start with the dumbbells at shoulder level, elbows bent and palms facing each other.","Press the dumbbells up and away from your body, extending your arms fully.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","प्रत्येक हाथ में डम्बल लेकर बेंच पर बैठें, हथेलियाँ एक-दूसरे के सामने हों।","अपने पैरों को मजबूती से जमीन पर रखें और अपनी पीठ को बेंच के सामने सीधा रखें।","कंधे के स्तर पर डम्बल से शुरुआत करें, कोहनियाँ मुड़ी हुई हों और हथेलियाँ एक-दूसरे के सामने हों।","अपनी भुजाओं को पूरी तरह फैलाते हुए डम्बल को अपने शरीर से ऊपर और दूर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1283', 'Dumbbell Incline Press On Exercise Ball', 'chest', 'pectorals', '["shoulders","triceps"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with a dumbbell in each hand, palms facing forward.","Slowly walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball.","Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.","Press the dumbbells upward, extending your arms fully.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ आगे की ओर रखते हुए, व्यायाम गेंद पर बैठें।","अपने पैरों को धीरे-धीरे आगे बढ़ाएं, अपने शरीर को गेंद के नीचे तब तक घुमाएं जब तक कि आपका सिर, गर्दन और पीठ का ऊपरी हिस्सा गेंद पर समर्थित न हो जाए।","डम्बल को कंधे के स्तर पर पकड़ें, कोहनियाँ मुड़ी हुई और किनारों की ओर इशारा करती हुई।","अपनी भुजाओं को पूरी तरह फैलाते हुए डम्बल को ऊपर की ओर दबाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0325', 'Dumbbell Incline Raise', 'shoulders', 'delts', '["trapezius","triceps"]', 'dumbbell', 'strength', NULL, '["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Lean back on the bench and raise the dumbbells to shoulder height, palms facing forward.","Keeping your back against the bench, exhale and raise the dumbbells above your head, fully extending your arms.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर अपनी जाँघों पर आराम करते हुए एक झुकी हुई बेंच पर बैठें।","बेंच पर पीछे झुकें और डम्बल को कंधे की ऊंचाई तक उठाएं, हथेलियाँ आगे की ओर हों।","अपनी पीठ को बेंच के सामने रखते हुए, सांस छोड़ें और अपनी बाहों को पूरी तरह फैलाते हुए डम्बल को अपने सिर के ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस कंधे की ऊंचाई तक ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0326', 'Dumbbell Incline Rear Lateral Raise', 'shoulders', 'delts', '["traps","rhomboids"]', 'dumbbell', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your chest against the backrest and hold a dumbbell in each hand.","Extend your arms straight down with your palms facing each other.","Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","अपनी छाती को पीछे की ओर रखते हुए बेंच पर बैठें और प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी हथेलियों को एक-दूसरे के सामने रखते हुए अपनी भुजाओं को सीधा नीचे फैलाएँ।","अपनी कोहनियों को थोड़ा मोड़ते हुए, अपनी भुजाओं को बगल की ओर तब तक उठाएँ जब तक वे ज़मीन के समानांतर न हो जाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0327', 'Dumbbell Incline Row', 'back', 'upper back', '["biceps","shoulders"]', 'dumbbell', 'strength', 'beginner', '["Set up an incline bench at a 45-degree angle.","Grab a dumbbell in each hand and sit on the bench with your chest against the incline.","Extend your arms fully, allowing the dumbbells to hang straight down from your shoulders.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","प्रत्येक हाथ में एक डम्बल पकड़ें और अपनी छाती को झुकाव के विपरीत रखते हुए बेंच पर बैठें।","अपनी बाहों को पूरी तरह फैलाएं, जिससे डम्बल सीधे आपके कंधों से नीचे लटक सकें।","अपने कंधे के ब्लेड को एक साथ दबाते हुए, डम्बल को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Dumbbell_Incline_Row/0.jpg","Dumbbell_Incline_Row/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0328', 'Dumbbell Incline Shoulder Raise', 'chest', 'serratus anterior', '["deltoids","trapezius"]', 'dumbbell', 'strength', 'beginner', '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down.","Rest the dumbbells on your thighs and lean back onto the bench.","Use your thighs to help raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing forward.","Exhale and slowly raise the dumbbells above your head, keeping a slight bend in your elbows.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back to shoulder height.","Repeat for the desired number of repetitions."]', '["एक झुकी हुई बेंच को 45 डिग्री के कोण पर सेट करें और दोनों हाथों में डम्बल लेकर, हथेलियाँ नीचे की ओर करके उस पर बैठें।","डम्बल को अपनी जाँघों पर टिकाएँ और वापस बेंच पर झुक जाएँ।","डम्बल को कंधे की ऊंचाई तक उठाने में मदद करने के लिए अपनी जांघों का उपयोग करें, फिर अपनी कलाइयों को घुमाएं ताकि आपकी हथेलियां आगे की ओर हों।","सांस छोड़ें और अपनी कोहनियों को हल्का सा मोड़ते हुए धीरे-धीरे डम्बल को अपने सिर के ऊपर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस कंधे की ऊंचाई तक ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Dumbbell_Incline_Shoulder_Raise/0.jpg","Dumbbell_Incline_Shoulder_Raise/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0329', 'Dumbbell Incline Shrug', 'back', 'traps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.","Place your feet flat on the ground and let your arms hang straight down with your palms facing your body.","Keeping your arms straight, shrug your shoulders up towards your ears as high as possible.","Hold the contraction for a moment, then slowly lower your shoulders back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक झुकी हुई बेंच को 45 डिग्री के कोण पर सेट करें और प्रत्येक हाथ में डम्बल लेकर उस पर बैठें।","अपने पैरों को ज़मीन पर सपाट रखें और अपनी हथेलियों को अपने शरीर की ओर रखते हुए अपनी भुजाओं को सीधा नीचे लटका दें।","अपनी भुजाओं को सीधा रखते हुए, अपने कंधों को जितना संभव हो सके अपने कानों की ओर ऊपर उठाएं।","एक क्षण के लिए संकुचन को रोककर रखें, फिर धीरे-धीरे अपने कंधों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3542', 'Dumbbell Incline T-Raise', 'shoulders', 'delts', '["traps","rhomboids"]', 'dumbbell', 'strength', NULL, '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Lean forward and let your arms hang straight down, perpendicular to the floor.","Keeping your arms straight, raise them out to the sides until they are parallel to the floor, forming a ''T'' shape with your body.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक झुकी हुई बेंच को 45 डिग्री के कोण पर सेट करें और उस पर दोनों हाथों में डंबल लेकर बैठें, हथेलियाँ अंदर की ओर हों।","आगे की ओर झुकें और अपनी भुजाओं को फर्श से सीधा नीचे की ओर लटका दें।","अपनी भुजाओं को सीधा रखते हुए, उन्हें बगल की ओर तब तक उठाएं जब तक कि वे फर्श के समानांतर न हो जाएं, जिससे आपके शरीर का ''टी'' आकार बन जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0330', 'Dumbbell Incline Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on an incline bench with a dumbbell in each hand, palms facing inwards.","Extend your arms fully overhead, keeping your elbows close to your head.","Lower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary.","Pause for a moment, then raise the dumbbells back to the starting position by extending your arms.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ अंदर की ओर रखते हुए, एक झुकी हुई बेंच पर बैठें।","अपनी कोहनियों को अपने सिर के पास रखते हुए, अपनी भुजाओं को पूरी तरह ऊपर की ओर फैलाएँ।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर डम्बल को अपने सिर के पीछे नीचे लाएँ।","एक क्षण के लिए रुकें, फिर अपनी बाहों को फैलाकर डम्बल को वापस प्रारंभिक स्थिति में उठाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0331', 'Dumbbell Incline Twisted Flyes', 'chest', 'pectorals', '["shoulders","triceps"]', 'dumbbell', 'strength', NULL, '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.","Lie back on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.","Lower the dumbbells out to the sides in a wide arc until you feel a stretch in your chest.","As you lower the dumbbells, rotate your wrists so that your palms face forward at the bottom of the movement.","Reverse the motion and bring the dumbbells back up to the starting position, squeezing your chest muscles together at the top.","Repeat for the desired number of repetitions."]', '["एक झुकी हुई बेंच को 45 डिग्री के कोण पर सेट करें और उस पर दोनों हाथों में डंबल लेकर बैठें, हथेलियाँ एक-दूसरे के सामने हों।","बेंच पर पीठ के बल लेट जाएं और अपनी बाहों को फैलाकर डंबल को सीधे अपनी छाती के ऊपर शुरुआती स्थिति में दबाएं।","जब तक आप अपनी छाती में खिंचाव महसूस न करें तब तक डम्बल को एक चौड़े चाप में बगल की ओर नीचे करें।","जैसे ही आप डम्बल को नीचे करते हैं, अपनी कलाइयों को घुमाएँ ताकि आपकी हथेलियाँ नीचे की ओर आगे की ओर हों।","गति को उल्टा करें और अपनी छाती की मांसपेशियों को शीर्ष पर एक साथ निचोड़ते हुए डम्बल को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1733', 'Dumbbell Incline Two Arm Extension', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.","Slowly lie back on the bench, keeping the dumbbells close to your chest.","Once you are fully lying down, extend your arms straight up towards the ceiling, keeping your elbows slightly bent.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर अपनी जाँघों पर आराम करते हुए एक झुकी हुई बेंच पर बैठें।","डम्बल को अपनी छाती के पास रखते हुए धीरे-धीरे बेंच पर वापस लेट जाएँ।","एक बार जब आप पूरी तरह से लेट जाएं, तो अपनी कोहनियों को थोड़ा मोड़ते हुए, अपनी बाहों को छत की ओर सीधा फैलाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3541', 'Dumbbell Incline Y-Raise', 'back', 'upper back', '["shoulders","rear deltoids"]', 'dumbbell', 'strength', NULL, '["Set an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.","Lean forward slightly and let your arms hang straight down, keeping a slight bend in your elbows.","Raise your arms out to the sides and up in a Y shape until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक झुकी हुई बेंच को 45 डिग्री के कोण पर सेट करें और उस पर दोनों हाथों में डंबल लेकर बैठें, हथेलियाँ अंदर की ओर हों।","थोड़ा आगे झुकें और अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी भुजाओं को सीधा नीचे लटका दें।","अपनी भुजाओं को Y आकार में बगल की ओर और ऊपर उठाएं जब तक कि वे जमीन के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0332', 'Dumbbell Iron Cross', 'shoulders', 'delts', '["triceps","chest"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body.","Pause for a moment, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, दोनों हाथों में एक-एक डंबल पकड़ लें।","अपनी भुजाओं को बगल की ओर तब तक उठाएं जब तक कि वे जमीन के समानांतर न हो जाएं, जिससे आपके शरीर का टी आकार बन जाए।","एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0333', 'Dumbbell Kickback', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your upper arms close to your sides, with your elbows bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ लें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी ऊपरी भुजाओं को अपनी भुजाओं के करीब लाएँ, अपनी कोहनियों को 90 डिग्री के कोण पर मोड़ें।","अपनी भुजाओं को पीछे की ओर सीधा फैलाएँ, अपनी ट्राइसेप्स को गति के शीर्ष पर दबाएँ।","एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-1734', 'Dumbbell Kickbacks On Exercise Ball', 'upper arms', 'triceps', '["shoulders","back"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle.","Extend your arms straight back, squeezing your triceps at the top of the movement.","Pause for a moment, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक व्यायाम बॉल पर बैठें।","अपनी हथेलियों को अंदर की ओर रखते हुए और अपनी बांहों को 90 डिग्री के कोण पर मोड़ते हुए प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी भुजाओं को पीछे की ओर सीधा फैलाएँ, अपनी ट्राइसेप्स को गति के शीर्ष पर दबाएँ।","एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1660', 'Dumbbell Kneeling Bicep Curl Exercise Ball', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Kneel on the floor with an exercise ball in front of you.","Place your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने सामने व्यायाम गेंद लेकर फर्श पर घुटने टेकें।","अपनी कोहनियों को व्यायाम बॉल के ऊपर रखें, अपनी हथेलियों को ऊपर की ओर रखते हुए प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए डम्बल को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0334', 'Dumbbell Lateral Raise', 'shoulders', 'delts', '["traps"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ें, हथेलियां आपके शरीर की ओर हों।","अपनी पीठ सीधी रखें और अपने कोर को संलग्न रखें।","अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी भुजाओं को बगल की ओर तब तक उठाएं जब तक कि वे फर्श के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 1, 'opengym', 1),
('og-0335', 'Dumbbell Lateral To Front Raise', 'shoulders', 'delts', '["trapezius","biceps"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the ground, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Next, raise your arms in front of you until they are parallel to the ground, again keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डम्बल पकड़ें और अपनी हथेलियों को अपने शरीर की ओर रखें।","अपनी पीठ सीधी रखें और अपने कोर को संलग्न रखें।","अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी भुजाओं को बगल की ओर तब तक उठाएं जब तक कि वे जमीन के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","इसके बाद, अपनी बाहों को अपने सामने तब तक उठाएं जब तक कि वे जमीन के समानांतर न हो जाएं, फिर से अपनी कोहनियों को थोड़ा सा मोड़ते रहें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0336', 'Dumbbell Lunge', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'dumbbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step forward with your right foot, lowering your body into a lunge position.","Keep your back straight and your chest up as you lower your body.","Push through your right heel to return to the starting position.","Repeat with your left leg.","Alternate legs for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डम्बल पकड़ें।","अपने दाहिने पैर से एक कदम आगे बढ़ाएं, अपने शरीर को नीचे झुकाकर स्थिति में लाएं।","अपने शरीर को नीचे करते समय अपनी पीठ सीधी और अपनी छाती ऊपर रखें।","प्रारंभिक स्थिति में लौटने के लिए अपनी दाहिनी एड़ी को धक्का दें।","अपने बाएँ पैर से दोहराएँ।","दोहराव की वांछित संख्या के लिए पैरों को वैकल्पिक करें।"]', '["Dumbbell_Lunges/0.jpg","Dumbbell_Lunges/1.jpg"]', 5, 'sets', 1, 'opengym', 1),
('og-1658', 'Dumbbell Lunge With Bicep Curl', 'upper arms', 'biceps', '["quadriceps","hamstrings"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.","Take a step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground.","As you lunge forward, simultaneously curl the dumbbells towards your shoulders, keeping your elbows close to your body.","Pause for a moment at the bottom of the lunge, then push through your right heel to return to the starting position, lowering the dumbbells back down to your sides.","Repeat the lunge and bicep curl on the opposite side, stepping forward with your left foot.","Continue alternating sides for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, अपनी हथेलियों को आगे की ओर रखते हुए प्रत्येक हाथ में डंबल पकड़ें।","अपने दाहिने पैर से एक कदम आगे बढ़ाएं, अपने शरीर को नीचे झुकाकर स्थिति में लाएं। आपका दाहिना घुटना 90 डिग्री के कोण पर मुड़ा होना चाहिए और आपका बायां घुटना जमीन के ठीक ऊपर होना चाहिए।","जैसे ही आप आगे बढ़ते हैं, साथ ही अपनी कोहनियों को अपने शरीर के करीब रखते हुए, डम्बल को अपने कंधों की ओर मोड़ें।","लंज के निचले हिस्से में एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी दाहिनी एड़ी से धक्का दें, डम्बल को वापस अपनी तरफ नीचे करें।","अपने बाएं पैर से आगे बढ़ते हुए, विपरीत दिशा में लंज और बाइसेप कर्ल को दोहराएं।","दोहराव की वांछित संख्या के लिए पक्षों को बदलना जारी रखें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0337', 'Dumbbell Lying Extension (Across Face)', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.","Hold a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other.","Keeping your upper arms stationary, slowly lower the dumbbell in an arc behind your head until your forearms are parallel to the ground.","Pause for a moment, then contract your triceps to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपने पैरों को ज़मीन पर सपाट करके और अपने सिर को बेंच के अंत में रखकर सीधे लेट जाएँ।","दोनों हाथों से डम्बल पकड़ें और अपनी बाहों को अपनी छाती के ऊपर सीधा फैलाएँ, हथेलियाँ एक-दूसरे के सामने हों।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, धीरे-धीरे डम्बल को अपने सिर के पीछे एक चाप में नीचे लाएँ जब तक कि आपकी भुजाएँ ज़मीन के समानांतर न हो जाएँ।","एक पल के लिए रुकें, फिर डम्बल को प्रारंभिक स्थिति में वापस लाने के लिए अपने ट्राइसेप्स को सिकोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1729', 'Dumbbell Lying Alternate Extension', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended.","Pause for a moment at the bottom, then raise the dumbbell back up to the starting position.","Repeat with the other arm, alternating sides for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ एक-दूसरे के सामने रखते हुए, एक बेंच पर सीधे लेट जाएँ।","अपनी कोहनियों को हल्का सा मोड़ते हुए, अपनी बाहों को अपनी छाती के ऊपर सीधा फैलाएँ।","एक डम्बल को अपने सिर की ओर नीचे करें, कोहनी पर झुकें, जबकि दूसरे हाथ को फैलाए रखें।","नीचे एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए पक्षों को बारी-बारी से दूसरे हाथ से दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0338', 'Dumbbell Lying Elbow Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest.","Lower the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary.","Pause for a moment at the bottom, then press the dumbbells back up to the starting position by extending your elbows.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर एक बेंच पर सीधे लेट जाएँ, हथेलियाँ एक-दूसरे के सामने हों और बाहें आपकी छाती के ऊपर सीधी फैली हुई हों।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपनी कोहनियों को मोड़कर डम्बल को अपने कंधों की ओर नीचे करें।","नीचे एक क्षण के लिए रुकें, फिर अपनी कोहनियों को फैलाकर डम्बल को वापस प्रारंभिक स्थिति में दबाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0863', 'Dumbbell Lying External Shoulder Rotation', 'shoulders', 'delts', '["rotator cuff","triceps"]', 'dumbbell', 'strength', NULL, '["Lie on your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees.","Hold a dumbbell in your hand with your palm facing down.","Keeping your upper arm against your side, slowly rotate your forearm upward as far as possible.","Pause for a moment at the top, then slowly lower your forearm back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["एक सपाट बेंच पर अपनी तरफ से लेटें, अपनी ऊपरी भुजा को अपनी तरफ रखें और आपकी कोहनी 90 डिग्री पर मुड़ी हुई हो।","अपनी हथेली नीचे की ओर रखते हुए अपने हाथ में डम्बल पकड़ें।","अपनी ऊपरी भुजा को बगल में रखते हुए, जहाँ तक संभव हो अपनी अग्रबाहु को धीरे-धीरे ऊपर की ओर घुमाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी बांह को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0339', 'Dumbbell Lying Femoral', 'upper legs', 'hamstrings', '["glutes"]', 'dumbbell', 'strength', NULL, '["Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen.","Bend your knees and bring the dumbbell towards your glutes, keeping your feet flat on the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और पेट के निचले हिस्से पर डम्बल रखकर अपनी पीठ के बल सीधे लेट जाएँ।","अपने घुटनों को मोड़ें और अपने पैरों को ज़मीन पर सपाट रखते हुए डम्बल को अपने ग्लूट्स की ओर लाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0340', 'Dumbbell Lying Hammer Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up.","Lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.","Press the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर एक बेंच पर सीधे लेट जाएँ, हथेलियाँ एक-दूसरे के सामने हों और भुजाएँ सीधी ऊपर की ओर फैली हुई हों।","अपनी कोहनियों को 90 डिग्री के कोण पर रखते हुए, डम्बल को अपनी छाती के किनारों पर नीचे करें।","अपनी भुजाओं को पूरी तरह फैलाते हुए डम्बल को वापस प्रारंभिक स्थिति में दबाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-2470', 'Dumbbell Lying On Floor Rear Delt Raise', 'shoulders', 'delts', '["trapezius","rhomboids"]', 'dumbbell', 'strength', NULL, '["Lie face down on the floor with a dumbbell in each hand, palms facing each other.","Extend your arms straight out in front of you, keeping a slight bend in your elbows.","Engaging your shoulder muscles, lift your arms up and out to the sides, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ एक-दूसरे के सामने रखते हुए, फर्श पर मुँह करके लेट जाएँ।","अपनी कोहनियों को हल्का सा मोड़ते हुए, अपनी भुजाओं को अपने सामने सीधा फैलाएँ।","अपने कंधे की मांसपेशियों को शामिल करते हुए, अपनी भुजाओं को ऊपर और बगल की ओर उठाएं, अपने कंधे के ब्लेड को एक साथ निचोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0341', 'Dumbbell Lying One Arm Deltoid Rear', 'shoulders', 'delts', '["trapezius","rhomboids"]', 'dumbbell', 'strength', NULL, '["Lie face down on a flat bench with a dumbbell in one hand, palm facing inwards.","Extend your arm straight down towards the floor, keeping it close to your body.","Raise your arm up and back, squeezing your shoulder blade towards your spine.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["एक सपाट बेंच पर मुंह के बल लेट जाएं और एक हाथ में डंबल लें, हथेली अंदर की ओर रखें।","अपने हाथ को अपने शरीर के करीब रखते हुए सीधे नीचे फर्श की ओर फैलाएँ।","अपने हाथ को ऊपर और पीछे उठाएं, अपने कंधे के ब्लेड को अपनी रीढ़ की ओर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने हाथ को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0343', 'Dumbbell Lying One Arm Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with a dumbbell in one hand and your feet flat on the ground.","Hold the dumbbell at shoulder level with your palm facing forward.","Press the dumbbell upward until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["एक हाथ में डम्बल लेकर एक बेंच पर सीधे लेट जाएँ और आपके पैर ज़मीन पर सीधे रहें।","अपनी हथेली को आगे की ओर रखते हुए डम्बल को कंधे के स्तर पर पकड़ें।","डम्बल को तब तक ऊपर की ओर दबाएँ जब तक आपका हाथ पूरी तरह फैल न जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0342', 'Dumbbell Lying One Arm Press v. 2', 'chest', 'pectorals', '["triceps","shoulders"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with your back supported and feet flat on the ground.","Hold a dumbbell in one hand with your palm facing towards your feet.","Extend your arm straight up towards the ceiling, keeping your elbow slightly bent.","Slowly lower the dumbbell down towards your chest, keeping your elbow close to your body.","Pause for a moment at the bottom, then push the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपनी पीठ को सहारा देकर और पैरों को ज़मीन पर सपाट रखते हुए एक बेंच पर सीधे लेट जाएँ।","अपनी हथेली को अपने पैरों की ओर रखते हुए एक हाथ में डम्बल पकड़ें।","अपनी बांह को छत की ओर सीधा फैलाएं, अपनी कोहनी को थोड़ा मोड़कर रखें।","अपनी कोहनी को अपने शरीर के करीब रखते हुए धीरे-धीरे डम्बल को अपनी छाती की ओर नीचे लाएँ।","नीचे एक क्षण के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0344', 'Dumbbell Lying One Arm Pronated Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder.","Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपनी पीठ और सिर को सहारा देकर एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों।","अपनी हथेली को नीचे की ओर रखते हुए एक हाथ में डम्बल पकड़ें और अपने हाथ को सीधे अपने कंधे के ऊपर फैलाएँ।","अपनी ऊपरी भुजा को स्थिर रखते हुए, अपनी कोहनी को मोड़कर धीरे-धीरे डम्बल को अपने सिर के पीछे नीचे लाएँ।","नीचे एक पल के लिए रुकें, फिर अपना हाथ वापस प्रारंभिक स्थिति तक बढ़ाएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0345', 'Dumbbell Lying One Arm Rear Lateral Raise', 'shoulders', 'delts', '["traps","rhomboids"]', 'dumbbell', 'strength', 'intermediate', '["Lie face down on a flat bench with a dumbbell in one hand, hanging towards the floor.","Keep your arm straight and lift the dumbbell out to the side, away from your body.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["एक सपाट बेंच पर मुंह के बल लेट जाएं और एक हाथ में डंबल फर्श की ओर लटका लें।","अपनी भुजा सीधी रखें और डम्बल को अपने शरीर से दूर बगल की ओर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', '["Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/0.jpg","Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0346', 'Dumbbell Lying One Arm Supinated Triceps Extension', 'upper arms', 'triceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in one hand with an underhand grip, and extend your arm straight up above your shoulder.","Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.","Pause for a moment at the bottom, then extend your arm back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपनी पीठ और सिर को सहारा देकर एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों।","एक हाथ में डंबल को अंडरहैंड ग्रिप से पकड़ें और अपने हाथ को अपने कंधे के ऊपर सीधा ऊपर उठाएं।","अपनी ऊपरी भुजा को स्थिर रखते हुए, अपनी कोहनी को मोड़कर धीरे-धीरे डम्बल को अपने सिर के पीछे नीचे लाएँ।","नीचे एक पल के लिए रुकें, फिर अपना हाथ वापस प्रारंभिक स्थिति तक बढ़ाएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0347', 'Dumbbell Lying Pronation', 'lower arms', 'forearms', '["biceps","shoulders"]', 'dumbbell', 'strength', 'intermediate', '["Lie flat on a bench with your chest facing down and your arms extended straight down, holding a dumbbell in each hand.","Rotate your palms so they are facing up.","Keeping your upper arms stationary, exhale and curl the dumbbells as you rotate your palms to face down.","Inhale and slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर सीधे लेट जाएं, आपकी छाती नीचे की ओर हो और आपकी भुजाएं सीधी नीचे की ओर फैली हुई हों, प्रत्येक हाथ में डम्बल पकड़ें।","अपनी हथेलियों को घुमाएं ताकि वे ऊपर की ओर हों।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, सांस छोड़ें और अपनी हथेलियों को नीचे की ओर घुमाते हुए डम्बल को मोड़ें।","श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Dumbbell_Lying_Pronation/0.jpg","Dumbbell_Lying_Pronation/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-2705', 'Dumbbell Lying Pronation On Floor', 'lower arms', 'forearms', '["biceps","triceps"]', 'dumbbell', 'strength', NULL, '["Lie flat on the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.","Rotate your palms so they are facing down towards the floor.","Keeping your arms straight, lift the dumbbells off the floor by contracting your forearms.","Continue lifting until your forearms are fully contracted and the dumbbells are at shoulder level.","Hold for a moment, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपना चेहरा नीचे करके फर्श पर सपाट लेट जाएं और आपकी भुजाएं आपके सामने सीधी फैली हुई हों, प्रत्येक हाथ में डम्बल पकड़ें।","अपनी हथेलियों को इस प्रकार घुमाएँ कि उनका मुख नीचे फर्श की ओर हो।","अपनी भुजाओं को सीधा रखते हुए, अपने अग्रबाहुओं को सिकोड़कर डम्बल को फर्श से उठाएं।","तब तक उठाना जारी रखें जब तक कि आपके अग्रबाहु पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1284', 'Dumbbell Lying Pullover On Exercise Ball', 'chest', 'pectorals', '["triceps","shoulders","back"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball and roll forward until your upper back is resting on the ball.","Hold a dumbbell with both hands and extend your arms straight up over your chest.","Slowly lower the dumbbell behind your head while keeping your arms straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["एक व्यायाम गेंद पर बैठें और तब तक आगे बढ़ें जब तक कि आपकी पीठ का ऊपरी हिस्सा गेंद पर न टिक जाए।","दोनों हाथों से डम्बल पकड़ें और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी भुजाओं को सीधा रखते हुए धीरे-धीरे डम्बल को अपने सिर के पीछे नीचे लाएँ।","एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1328', 'Dumbbell Lying Rear Delt Row', 'back', 'upper back', '["shoulders","biceps"]', 'dumbbell', 'strength', NULL, '["Lie face down on a flat bench with a dumbbell in each hand, palms facing inwards.","Extend your arms straight down towards the floor, keeping a slight bend in your elbows.","Engaging your back muscles, lift the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ अंदर की ओर रखते हुए, एक सपाट बेंच पर लेट जाएँ।","अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी भुजाओं को फर्श की ओर सीधा फैलाएँ।","अपनी पीठ की मांसपेशियों को शामिल करते हुए, डम्बल को अपनी छाती की ओर ऊपर उठाएं, अपने कंधे के ब्लेड को एक साथ दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0348', 'Dumbbell Lying Rear Lateral Raise', 'shoulders', 'delts', '["traps","rhomboids"]', 'dumbbell', 'strength', 'intermediate', '["Lie face down on a flat bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight down towards the floor, keeping a slight bend in your elbows.","Engaging your shoulder muscles, lift your arms out to the sides until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ एक-दूसरे के सामने रखते हुए, एक सपाट बेंच पर लेट जाएँ।","अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी भुजाओं को फर्श की ओर सीधा फैलाएँ।","अपने कंधे की मांसपेशियों को शामिल करते हुए, अपनी भुजाओं को बगल की ओर तब तक उठाएं जब तक कि वे फर्श के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Dumbbell_Lying_Rear_Lateral_Raise/0.jpg","Dumbbell_Lying_Rear_Lateral_Raise/1.jpg"]', 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1735', 'Dumbbell Lying Single Extension', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest.","Lower the dumbbell in a controlled manner towards your forehead, keeping your upper arm stationary.","Pause briefly at the bottom of the movement, then extend your arm back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["एक हाथ में डम्बल लेकर एक बेंच पर सीधे लेट जाएँ और आपका हाथ आपकी छाती के ऊपर पूरी तरह फैला हुआ हो।","अपने ऊपरी बांह को स्थिर रखते हुए, डम्बल को अपने माथे की ओर नियंत्रित तरीके से नीचे लाएँ।","गति के निचले भाग पर कुछ देर रुकें, फिर अपने हाथ को वापस प्रारंभिक स्थिति में फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0349', 'Dumbbell Lying Supination', 'lower arms', 'forearms', '["biceps","shoulders"]', 'dumbbell', 'strength', 'intermediate', '["Lie flat on a bench with your feet flat on the ground.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, curl the dumbbells towards your shoulders by contracting your forearms.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट रखते हुए एक बेंच पर सीधे लेट जाएँ।","अपनी हथेलियों को ऊपर की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए, अपने अग्रबाहुओं को सिकोड़कर डम्बल को अपने कंधों की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Dumbbell_Lying_Supination/0.jpg","Dumbbell_Lying_Supination/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-2706', 'Dumbbell Lying Supination On Floor', 'lower arms', 'forearms', '["biceps","shoulders"]', 'dumbbell', 'strength', NULL, '["Lie flat on your back on the floor with your legs extended and your arms by your sides, holding a dumbbell in each hand.","Rotate your palms to face up, keeping your elbows close to your sides.","Slowly curl the dumbbells towards your shoulders, squeezing your forearms.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को फैलाकर और अपनी भुजाओं को बगल में रखकर फर्श पर अपनी पीठ के बल लेट जाएँ, प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी हथेलियों को ऊपर की ओर घुमाएँ, अपनी कोहनियों को अपनी भुजाओं के पास रखें।","धीरे-धीरे डम्बल को अपने कंधों की ओर मोड़ें, अपने अग्रबाहुओं को सिकोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1661', 'Dumbbell Lying Supine Biceps Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with your back and head supported, and your feet flat on the ground.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ और सिर को सहारा देकर एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों।","अपनी हथेलियों को ऊपर की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0350', 'Dumbbell Lying Supine Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'beginner', '["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर एक बेंच पर सीधे लेट जाएँ, हथेलियाँ ऊपर की ओर हों और बाहें पूरी तरह फैली हुई हों।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Lying_Supine_Dumbbell_Curl/0.jpg","Lying_Supine_Dumbbell_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0351', 'Dumbbell Lying Triceps Extension', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', 'intermediate', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other.","Extend your arms straight up over your chest, keeping your elbows close to your body.","Lower the dumbbells down towards your forehead, bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ एक-दूसरे के सामने रखते हुए, एक बेंच पर सीधे लेट जाएँ।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए, अपनी बाहों को अपनी छाती के ऊपर सीधा फैलाएँ।","अपनी कोहनियों को झुकाते हुए डम्बल को अपने माथे की ओर नीचे करें।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Lying_Dumbbell_Tricep_Extension/0.jpg","Lying_Dumbbell_Tricep_Extension/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1662', 'Dumbbell Lying Wide Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर एक बेंच पर सीधे लेट जाएँ, हथेलियाँ ऊपर की ओर हों और बाहें पूरी तरह फैली हुई हों।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0352', 'Dumbbell Neutral Grip Bench Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'dumbbell', 'strength', 'beginner', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.","Hold a dumbbell in each hand with a neutral grip (palms facing each other) and your arms extended straight up over your chest.","Slowly lower the dumbbells down towards your chest, keeping your elbows close to your body.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position, fully extending your arms.","Repeat for the desired number of repetitions."]', '["एक बेंच पर सीधे लेट जाएं और आपके पैर जमीन पर सपाट हों और आपकी पीठ बेंच से सटी हुई हो।","प्रत्येक हाथ में डम्बल को तटस्थ पकड़ (हथेलियाँ एक दूसरे के सामने) के साथ पकड़ें और आपकी बाहें सीधे आपकी छाती के ऊपर फैली हुई हों।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए धीरे-धीरे डम्बल को अपनी छाती की ओर नीचे लाएँ।","नीचे एक पल के लिए रुकें, फिर अपनी बाहों को पूरी तरह फैलाते हुए डम्बल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Dumbbell_Bench_Press_with_Neutral_Grip/0.jpg","Dumbbell_Bench_Press_with_Neutral_Grip/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1285', 'Dumbbell One Arm Bench Fly', 'chest', 'pectorals', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on a flat bench with a dumbbell in one hand, resting it on top of your thigh.","Lie back on the bench, keeping the dumbbell pressed against your thigh.","Using your free hand, help lift the dumbbell up to the starting position.","Hold the dumbbell directly above your shoulder with your arm extended and palm facing inward.","Lower the dumbbell out to the side in a wide arc, keeping a slight bend in your elbow.","Pause when your arm is parallel to the ground, then reverse the movement and bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."]', '["एक हाथ में डंबल लेकर एक सपाट बेंच पर बैठें, इसे अपनी जांघ के ऊपर रखें।","डम्बल को अपनी जाँघ पर दबाते हुए बेंच पर पीठ के बल लेट जाएँ।","अपने खाली हाथ का उपयोग करके, डम्बल को प्रारंभिक स्थिति तक उठाने में मदद करें।","अपनी बांह को फैलाकर और हथेली को अंदर की ओर रखते हुए डम्बल को सीधे अपने कंधे के ऊपर पकड़ें।","अपनी कोहनी को थोड़ा मोड़ते हुए, डम्बल को एक चौड़े चाप में बगल की ओर नीचे करें।","जब आपकी भुजा ज़मीन के समानांतर हो तो रुकें, फिर गति को उल्टा करें और डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0292', 'Dumbbell One Arm Bent-Over Row', 'back', 'upper back', '["biceps","forearms"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and your core engaged.","Let the dumbbell hang straight down towards the floor, with your arm fully extended.","Pull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ में डंबल पकड़ें और अपनी हथेली को अपने शरीर की ओर रखें।","अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपनी भुजा को पूरी तरह फैलाकर डम्बल को फर्श की ओर सीधा लटका रहने दें।","अपनी कोहनी को अपने शरीर के पास रखते हुए और अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, डम्बल को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1286', 'Dumbbell One Arm Chest Fly On Exercise Ball', 'chest', 'pectorals', '["shoulders","triceps"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Walk your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball.","Extend your arm with the dumbbell straight up above your chest, palm facing inward.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment when your arm is parallel to the ground.","Engage your chest muscles to bring the dumbbell back up to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["एक हाथ में डम्बल लेकर व्यायाम बॉल पर बैठें और आपके पैर ज़मीन पर सपाट हों।","अपने पैरों को आगे की ओर घुमाएँ, गेंद को तब तक घुमाएँ जब तक कि आपकी ऊपरी पीठ को गेंद पर सहारा न मिल जाए और आपका सिर, गर्दन और कंधे गेंद से दूर न हो जाएँ।","अपनी बांह को डंबल के साथ सीधे अपनी छाती के ऊपर फैलाएं, हथेली अंदर की ओर हो।","अपनी कोहनी को थोड़ा मोड़ते हुए धीरे-धीरे डम्बल को बगल की ओर नीचे करें।","जब आपकी बांह ज़मीन के समानांतर हो तो एक क्षण रुकें।","डम्बल को शुरुआती स्थिति में वापस लाने के लिए अपनी छाती की मांसपेशियों को शामिल करें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0353', 'Dumbbell One Arm Concentration Curl (On Stability Ball)', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in one hand with your palm facing up and your arm extended down towards the floor.","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder while contracting your biceps.","Pause for a moment at the top of the movement, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms and repeat."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को 90 डिग्री के कोण पर मोड़कर एक स्टेबिलिटी बॉल पर बैठें।","अपनी हथेली को ऊपर की ओर रखते हुए एक हाथ में डम्बल पकड़ें और अपना हाथ नीचे फर्श की ओर फैला हुआ रखें।","अपनी कोहनी को अपनी जांघ के अंदर, घुटने के ठीक ऊपर रखें।","अपनी ऊपरी बांह को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए डंबल को अपने कंधे की ओर मोड़ें।","गति के शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1287', 'Dumbbell One Arm Decline Chest Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'dumbbell', 'strength', NULL, '["Lie on a decline bench with a dumbbell in one hand, resting on your chest.","Place your feet flat on the ground and keep your back pressed against the bench.","Extend your arm and push the dumbbell up towards the ceiling, fully extending your elbow.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["एक हाथ में डम्बल लेकर अपनी छाती पर आराम करते हुए डिक्लाइन बेंच पर लेट जाएँ।","अपने पैरों को ज़मीन पर सपाट रखें और अपनी पीठ को बेंच से सटाकर रखें।","अपनी बांह बढ़ाएं और अपनी कोहनी को पूरी तरह फैलाते हुए डंबल को छत की ओर धकेलें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1288', 'Dumbbell One Arm Fly On Exercise Ball', 'chest', 'pectorals', '["shoulders","triceps"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with a dumbbell in one hand and your feet flat on the ground.","Walk your feet forward and roll your body down until your upper back is resting on the exercise ball.","Extend your arm with the dumbbell straight up above your chest, palm facing inwards.","Slowly lower the dumbbell out to the side, keeping a slight bend in your elbow.","Pause for a moment, then squeeze your chest muscles to bring the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["एक हाथ में डम्बल लेकर व्यायाम बॉल पर बैठें और आपके पैर ज़मीन पर सपाट हों।","अपने पैरों को आगे की ओर बढ़ाएं और अपने शरीर को तब तक नीचे की ओर घुमाएं जब तक कि आपकी ऊपरी पीठ व्यायाम गेंद पर आराम न कर ले।","अपनी बांह को डंबल के साथ सीधे अपनी छाती के ऊपर फैलाएं, हथेली अंदर की ओर हो।","अपनी कोहनी को थोड़ा मोड़ते हुए धीरे-धीरे डम्बल को बगल की ओर नीचे करें।","एक पल के लिए रुकें, फिर डम्बल को शुरुआती स्थिति में वापस लाने के लिए अपनी छाती की मांसपेशियों को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1736', 'Dumbbell One Arm French Press On Exercise Ball', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle.","Extend your arm straight up towards the ceiling, keeping your elbow stationary.","Slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक व्यायाम बॉल पर बैठें।","अपनी हथेली को ऊपर की ओर रखते हुए और अपनी कोहनी को 90 डिग्री के कोण पर मोड़ते हुए एक हाथ में डम्बल पकड़ें।","अपनी कोहनी को स्थिर रखते हुए, अपने हाथ को छत की ओर सीधा फैलाएँ।","धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1663', 'Dumbbell One Arm Hammer Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.","Hold the dumbbell with a neutral grip (palms facing your body).","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["एक हाथ में डम्बल और अपने ऊपरी हाथ को पैड पर टिकाकर उपदेशक बेंच पर बैठें।","डम्बल को तटस्थ पकड़ से पकड़ें (हथेलियाँ आपके शरीर की ओर)।","अपनी ऊपरी भुजा को स्थिर रखते हुए सांस छोड़ें और डंबल को अपने कंधे की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1621', 'Dumbbell One Arm Hammer Press On Exercise Ball', 'upper arms', 'triceps', '["shoulders","chest"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle.","Place your other hand on your hip for stability.","Press the dumbbell upwards, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक व्यायाम बॉल पर बैठें।","अपनी हथेली को अंदर की ओर रखते हुए और अपनी कोहनी को 90 डिग्री के कोण पर मोड़ते हुए एक हाथ में डंबल पकड़ें।","स्थिरता के लिए अपना दूसरा हाथ अपने कूल्हे पर रखें।","अपनी बांह को पूरी तरह फैलाते हुए डंबल को ऊपर की ओर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1289', 'Dumbbell One Arm Incline Chest Press', 'chest', 'pectorals', '["shoulders","triceps"]', 'dumbbell', 'strength', NULL, '["Adjust the incline bench to a 45-degree angle.","Sit on the bench with your back against the pad and feet flat on the ground.","Hold a dumbbell in one hand with an overhand grip, resting it on your shoulder.","Push the dumbbell up and away from your body, extending your arm fully.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["झुकी हुई बेंच को 45 डिग्री के कोण पर समायोजित करें।","बेंच पर अपनी पीठ पैड से सटाकर और पैरों को ज़मीन पर सपाट करके बैठें।","एक हाथ में डम्बल को ओवरहैंड ग्रिप से पकड़ें, इसे अपने कंधे पर रखें।","अपने हाथ को पूरी तरह फैलाते हुए डम्बल को अपने शरीर से ऊपर और दूर धकेलें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0354', 'Dumbbell One Arm Kickback', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Bring your right elbow up to your side, keeping it bent at a 90-degree angle.","Extend your right arm straight back, squeezing your triceps at the top of the movement.","Slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और अपने दाहिने हाथ में डंबल पकड़ लें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी दाहिनी कोहनी को 90 डिग्री के कोण पर मोड़ते हुए अपनी तरफ ऊपर लाएँ।","अपने दाहिने हाथ को सीधा पीछे की ओर फैलाएँ, अपने ट्राइसेप्स को गति के शीर्ष पर दबाएँ।","धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0355', 'Dumbbell One Arm Lateral Raise', 'shoulders', 'delts', '["trapezius","triceps"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your palm facing your body.","Keep your back straight and your core engaged throughout the exercise.","Raise the dumbbell to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ में डंबल पकड़ें और अपनी हथेली को अपने शरीर की ओर रखें।","पूरे अभ्यास के दौरान अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपनी बांह सीधी और हथेली नीचे की ओर रखते हुए डम्बल को बगल की ओर उठाएं।","तब तक उठाना जारी रखें जब तक आपकी भुजा जमीन के समानांतर न हो जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0356', 'Dumbbell One Arm Lateral Raise With Support', 'shoulders', 'delts', '["trapezius","rotator cuff"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand, with your palm facing your body.","Place your other hand on a stable surface, such as a bench or wall, for support.","Keep your back straight and engage your core.","Raise the dumbbell out to the side, keeping your arm straight and your palm facing down.","Continue lifting until your arm is parallel to the ground.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch sides."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में डंबल पकड़ लें, आपकी हथेली आपके शरीर की ओर हो।","समर्थन के लिए अपने दूसरे हाथ को किसी स्थिर सतह, जैसे बेंच या दीवार पर रखें।","अपनी पीठ सीधी रखें और अपने कोर को संलग्न रखें।","अपनी बांह सीधी और हथेली नीचे की ओर रखते हुए डम्बल को बगल की ओर उठाएं।","तब तक उठाना जारी रखें जब तक आपकी भुजा जमीन के समानांतर न हो जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पक्ष बदलें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1290', 'Dumbbell One Arm Press On Exercise Ball', 'chest', 'pectorals', '["shoulders","triceps","core"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell in one hand and position it at shoulder height, with your elbow bent and palm facing forward.","Slowly press the dumbbell upward until your arm is fully extended, while keeping your core engaged and maintaining balance on the exercise ball.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को 90 डिग्री के कोण पर मोड़कर एक व्यायाम बॉल पर बैठें।","एक हाथ में डम्बल पकड़ें और इसे कंधे की ऊंचाई पर रखें, अपनी कोहनी मोड़ें और हथेली आगे की ओर रखें।","धीरे-धीरे डंबल को ऊपर की ओर दबाएं जब तक कि आपकी बांह पूरी तरह से विस्तारित न हो जाए, जबकि अपने कोर को व्यस्त रखें और व्यायाम बॉल पर संतुलन बनाए रखें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1665', 'Dumbbell One Arm Prone Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Lie face down on a flat bench with a dumbbell in one hand, palm facing down.","Extend your arm fully, letting it hang straight down towards the floor.","Keeping your upper arm stationary, curl the dumbbell up towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["एक हाथ में डम्बल लेकर, हथेली नीचे की ओर रखते हुए, एक सपाट बेंच पर मुंह करके लेट जाएं।","अपनी बांह को पूरी तरह फैलाएं, उसे सीधे नीचे फर्श की ओर लटकने दें।","अपनी ऊपरी भुजा को स्थिर रखते हुए, अपने बाइसेप्स को सिकोड़कर डंबल को अपने कंधे की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1666', 'Dumbbell One Arm Prone Hammer Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended.","Keep your upper arm stationary and curl the dumbbell towards your shoulder, contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["एक हाथ में डम्बल लेकर एक सपाट बेंच पर मुंह के बल लेट जाएं, हथेली आपके शरीर की ओर हो और हाथ पूरी तरह फैला हुआ हो।","अपनी ऊपरी बांह को स्थिर रखें और अपने बाइसेप्स को सिकोड़ते हुए डंबल को अपने कंधे की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1291', 'Dumbbell One Arm Pullover On Exercise Ball', 'chest', 'pectorals', '["triceps","latissimus dorsi","rhomboids"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.","Hold a dumbbell with one hand and extend your arm straight up above your chest.","Slowly lower the dumbbell behind your head while keeping your arm straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को 90 डिग्री के कोण पर मोड़कर एक व्यायाम बॉल पर बैठें।","एक हाथ से डम्बल पकड़ें और अपने हाथ को सीधे अपनी छाती के ऊपर फैलाएँ।","अपने हाथ को सीधा रखते हुए धीरे-धीरे डम्बल को अपने सिर के पीछे नीचे लाएँ।","एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-0358', 'Dumbbell One Arm Reverse Wrist Curl', 'lower arms', 'forearms', '["wrist extensors"]', 'dumbbell', 'strength', NULL, '["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in one hand with an overhand grip, palm facing down.","Rest your forearm on your thigh, with your wrist hanging off the edge.","Slowly lower the dumbbell towards the ground by flexing your wrist.","Pause for a moment at the bottom, then slowly curl your wrist back up towards your body.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने पैरों को ज़मीन पर सपाट करके किसी बेंच या कुर्सी पर बैठें।","एक हाथ में डम्बल को ओवरहैंड ग्रिप से पकड़ें, हथेली नीचे की ओर हो।","अपनी कलाई को किनारे से लटकाते हुए अपनी बांह को अपनी जांघ पर टिकाएं।","अपनी कलाई को मोड़कर धीरे-धीरे डंबल को जमीन की ओर नीचे लाएं।","नीचे एक पल के लिए रुकें, फिर धीरे-धीरे अपनी कलाई को वापस अपने शरीर की ओर मोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0359', 'Dumbbell One Arm Reverse Fly (With Support)', 'shoulders', 'delts', '["trapezius","rhomboids"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing inwards.","Lean forward and place your free hand on the bench for support.","Keep your arm slightly bent and raise it out to the side until it is parallel to the ground.","Pause for a moment at the top, then slowly lower your arm back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा करके एक बेंच पर बैठें।","अपनी हथेली को अंदर की ओर रखते हुए एक हाथ में डम्बल पकड़ें।","आगे झुकें और समर्थन के लिए अपना खाली हाथ बेंच पर रखें।","अपनी भुजा को थोड़ा मोड़कर रखें और इसे बगल की ओर तब तक उठाएं जब तक कि यह जमीन के समानांतर न हो जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपने हाथ को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1622', 'Dumbbell One Arm Reverse Grip Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on a flat bench with a dumbbell in one hand, palm facing towards your body.","Place your feet flat on the ground and keep your back straight.","Raise the dumbbell to shoulder height, keeping your elbow close to your body.","Press the dumbbell upwards until your arm is fully extended.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["एक हाथ में डम्बल लेकर एक सपाट बेंच पर बैठें, हथेली आपके शरीर की ओर हो।","अपने पैरों को ज़मीन पर सपाट रखें और अपनी पीठ सीधी रखें।","अपनी कोहनी को अपने शरीर के करीब रखते हुए डम्बल को कंधे की ऊंचाई तक उठाएं।","डम्बल को तब तक ऊपर की ओर दबाएँ जब तक आपका हाथ पूरी तरह फैल न जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1414', 'Dumbbell One Arm Reverse Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with an underhand grip.","Lower the dumbbell slowly until your arm is fully extended.","Curl the dumbbell back up towards your shoulder, keeping your upper arm stationary.","Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["एक उपदेशक बेंच पर अपनी छाती को पैड से सटाकर और अपनी बांह को बेंच के किनारे पर फैलाकर बैठें, एक डम्बल को अंडरहैंड ग्रिप से पकड़ें।","डम्बल को धीरे-धीरे नीचे करें जब तक कि आपकी बांह पूरी तरह विस्तारित न हो जाए।","अपनी ऊपरी भुजा को स्थिर रखते हुए, डम्बल को वापस अपने कंधे की ओर मोड़ें।","गति के शीर्ष पर अपने बाइसेप्स को निचोड़ें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1667', 'Dumbbell One Arm Reverse Spider Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in one hand, palm facing down and arm fully extended.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by flexing your elbow.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["एक हाथ में डम्बल लेकर, हथेली नीचे की ओर और हाथ पूरी तरह फैलाकर सीधे खड़े हो जाएं।","अपनी ऊपरी बांह को स्थिर रखते हुए, अपनी कोहनी को मोड़कर डंबल को अपने कंधे की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1668', 'Dumbbell One Arm Seated Bicep Curl On Exercise Ball', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with your palm facing up and your arm fully extended.","Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक व्यायाम बॉल पर बैठें।","अपनी हथेली को ऊपर की ओर रखते हुए और अपने हाथ को पूरी तरह फैलाकर एक हाथ में डम्बल पकड़ें।","अपनी ऊपरी बांह को स्थिर रखते हुए, अपने बाइसेप्स को सिकोड़कर डंबल को अपने कंधे की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1669', 'Dumbbell One Arm Seated Hammer Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in one hand with a neutral grip (palms facing each other).","Rest your elbow on the inside of your thigh, just above the knee.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, squeezing your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","एक हाथ में तटस्थ पकड़ के साथ डम्बल पकड़ें (हथेलियाँ एक दूसरे के सामने)।","अपनी कोहनी को अपनी जांघ के अंदर, घुटने के ठीक ऊपर रखें।","अपनी ऊपरी भुजा को स्थिर रखते हुए सांस छोड़ें और डंबल को अपने कंधे की ओर मोड़ें।","अपने बाइसेप्स को निचोड़ते हुए शीर्ष पर एक पल के लिए रुकें।","श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1415', 'Dumbbell One Arm Seated Neutral Wrist Curl', 'lower arms', 'forearms', '["biceps","brachialis"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.","Rest your forearm on your thigh, allowing your wrist to hang off the edge.","Keeping your forearm stationary, curl your wrist upward as far as possible.","Pause for a moment at the top, then slowly lower your wrist back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other hand."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और एक हाथ में डम्बल पकड़ें, हथेली ऊपर की ओर रखें।","अपनी बांह को अपनी जांघ पर टिकाएं, जिससे आपकी कलाई किनारे से लटक जाए।","अपनी बांह को स्थिर रखते हुए, अपनी कलाई को जहां तक ​​संभव हो ऊपर की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी कलाई को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरी ओर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0361', 'Dumbbell One Arm Shoulder Press', 'shoulders', 'delts', '["triceps","upper back"]', 'dumbbell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.","Press the dumbbell upward until your arm is fully extended overhead.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में कंधे के स्तर पर डंबल पकड़ें, हथेली आगे की ओर हो।","डम्बल को तब तक ऊपर की ओर दबाएँ जब तक कि आपका हाथ पूरी तरह से ऊपर की ओर न फैल जाए।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', '["Dumbbell_One-Arm_Shoulder_Press/0.jpg","Dumbbell_One-Arm_Shoulder_Press/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0360', 'Dumbbell One Arm Shoulder Press v. 2', 'shoulders', 'delts', '["triceps","upper back"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand at shoulder level, palm facing forward.","Engage your core and press the dumbbell straight up overhead, fully extending your arm.","Pause for a moment at the top, then slowly lower the dumbbell back to shoulder level.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और एक हाथ में कंधे के स्तर पर डंबल पकड़ें, हथेली आगे की ओर हो।","अपने कोर को संलग्न करें और अपनी बांह को पूरी तरह फैलाते हुए डंबल को सीधे ऊपर की ओर दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस कंधे के स्तर तक नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-3888', 'Dumbbell One Arm Snatch', 'upper legs', 'glutes', '["hamstrings","quadriceps","core"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.","Lower the dumbbell towards the ground, keeping it close to your body.","Explosively extend your hips, knees, and ankles, driving the dumbbell upwards in a straight line.","As the dumbbell reaches shoulder height, quickly rotate your hand and punch it overhead, fully extending your arm.","Catch the dumbbell overhead with a slight bend in your knees and hips.","Lower the dumbbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ में डंबल को ओवरहैंड पकड़ के साथ पकड़ लें।","अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ सीधी और छाती ऊपर रखें।","डम्बल को अपने शरीर के पास रखते हुए जमीन की ओर नीचे करें।","अपने कूल्हों, घुटनों और टखनों को तेजी से फैलाएँ, डम्बल को एक सीधी रेखा में ऊपर की ओर ले जाएँ।","जैसे ही डम्बल कंधे की ऊंचाई तक पहुंचता है, तेजी से अपना हाथ घुमाएं और अपनी बांह को पूरी तरह फैलाते हुए इसे ऊपर की ओर मुक्का मारें।","अपने घुटनों और कूल्हों को थोड़ा मोड़कर डम्बल को ऊपर की ओर पकड़ें।","डम्बल को नियंत्रित तरीके से वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1670', 'Dumbbell One Arm Standing Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in one hand, palm facing forward and arm fully extended.","Keeping your upper arm stationary, exhale and curl the weight upward while contracting your biceps.","Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["एक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेली आगे की ओर और हाथ पूरी तरह फैला हुआ हो।","अपनी ऊपरी बांह को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को ऊपर की ओर मोड़ें।","डंबल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाए।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1671', 'Dumbbell One Arm Standing Hammer Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and your upper arms stationary.","Exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आपके धड़ की ओर हों।","अपनी कोहनियों को अपने धड़ के पास रखें और अपनी ऊपरी भुजाओं को स्थिर रखें।","सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन मोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0362', 'Dumbbell One Arm Triceps Extension (On Bench)', 'upper arms', 'triceps', '["shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your back straight and feet flat on the ground.","Hold a dumbbell in one hand and place your other hand on the bench for support.","Raise the dumbbell overhead, keeping your upper arm close to your head and your elbow pointing forward.","Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.","Extend your arm back up to the starting position, fully straightening your elbow.","Repeat for the desired number of repetitions, then switch arms."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके एक बेंच पर बैठें।","एक हाथ में डम्बल पकड़ें और समर्थन के लिए अपने दूसरे हाथ को बेंच पर रखें।","डम्बल को ऊपर उठाएं, अपनी ऊपरी भुजा को अपने सिर के पास रखें और अपनी कोहनी को आगे की ओर रखें।","अपनी ऊपरी भुजा को स्थिर रखते हुए, अपनी कोहनी को मोड़कर डम्बल को अपने सिर के पीछे नीचे लाएँ।","अपनी कोहनी को पूरी तरह से सीधा करते हुए, अपनी भुजा को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0363', 'Dumbbell One Arm Upright Row', 'shoulders', 'delts', '["traps","biceps"]', 'dumbbell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.","Let the dumbbell hang at arm''s length in front of your thighs, with your palm facing your body.","Keeping your back straight and your core engaged, exhale and lift the dumbbell straight up towards your chin, leading with your elbow.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, एक हाथ में डंबल को ओवरहैंड पकड़ के साथ पकड़ लें।","डंबल को अपनी जांघों के सामने एक हाथ की दूरी पर लटकाएं, आपकी हथेली आपके शरीर की ओर हो।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, सांस छोड़ें और डंबल को अपनी कोहनी की मदद से सीधे अपनी ठुड्डी की ओर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', '["Dumbbell_One-Arm_Upright_Row/0.jpg","Dumbbell_One-Arm_Upright_Row/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0364', 'Dumbbell One Arm Wrist Curl', 'lower arms', 'forearms', '["biceps","brachialis"]', 'dumbbell', 'strength', NULL, '["Sit on a bench or chair with your feet flat on the ground.","Hold a dumbbell in one hand with an underhand grip, resting your forearm on your thigh.","Allow your wrist to extend, letting the dumbbell roll down towards your fingers.","Slowly curl your wrist back up, bringing the dumbbell towards your forearm.","Repeat for the desired number of repetitions, then switch to the other hand."]', '["अपने पैरों को ज़मीन पर सपाट करके किसी बेंच या कुर्सी पर बैठें।","एक हाथ में डम्बल पकड़ें, अपने अग्रबाहु को अपनी जाँघ पर टिकाएँ।","अपनी कलाई को फैलने दें, डम्बल को अपनी उंगलियों की ओर लुढ़कने दें।","धीरे-धीरे अपनी कलाई को पीछे की ओर मोड़ें, डम्बल को अपनी बांह की ओर लाएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरी ओर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1672', 'Dumbbell One Arm Zottman Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip.","Rest your upper arm on the preacher bench pad, allowing your arm to fully extend.","Curl the dumbbell up towards your shoulder, keeping your upper arm stationary.","At the top of the curl, rotate your wrist so that your palm faces up.","Slowly lower the dumbbell back down to the starting position, rotating your wrist back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["प्रीचर कर्ल बेंच पर बैठें और एक हाथ में डंबल को अंडरहैंड ग्रिप से पकड़ें।","अपनी ऊपरी बांह को उपदेशक बेंच पैड पर रखें, जिससे आपकी बांह पूरी तरह से फैल सके।","अपनी ऊपरी भुजा को स्थिर रखते हुए, डम्बल को अपने कंधे की ओर मोड़ें।","कर्ल के शीर्ष पर, अपनी कलाई को घुमाएं ताकि आपकी हथेली ऊपर की ओर रहे।","धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाएं, अपनी कलाई को वापस प्रारंभिक स्थिति में घुमाएँ।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1292', 'Dumbbell One Leg Fly On Exercise Ball', 'chest', 'pectorals', '["shoulders","triceps"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.","Place one foot on the ground and extend the other leg straight out in front of you.","Lean forward slightly and bring your arms out to the sides, keeping a slight bend in your elbows.","Slowly lower the dumbbells down and out to the sides, feeling a stretch in your chest.","Pause for a moment at the bottom, then squeeze your chest muscles to bring the dumbbells back up to the starting position.","Repeat for the desired number of repetitions, then switch legs and repeat."]', '["प्रत्येक हाथ में डम्बल लेकर व्यायाम गेंद पर बैठें, हथेलियाँ एक-दूसरे के सामने हों।","एक पैर को ज़मीन पर रखें और दूसरे पैर को अपने सामने सीधा फैला लें।","थोड़ा आगे झुकें और अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी भुजाओं को बगल की ओर लाएँ।","अपनी छाती में खिंचाव महसूस करते हुए धीरे-धीरे डम्बल को नीचे और बाहर की ओर नीचे करें।","नीचे एक पल के लिए रुकें, फिर डम्बल को शुरुआती स्थिति में वापस लाने के लिए अपनी छाती की मांसपेशियों को निचोड़ें।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर पैर बदलें और दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0365', 'Dumbbell Over Bench Neutral Wrist Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Keeping your upper arms stationary, exhale and curl the dumbbells up towards your shoulders.","Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और दोनों हाथों में एक-एक डम्बल पकड़ें, हथेलियाँ ऊपर की ओर हों।","अपनी बांहों को बेंच पर टिकाएं, जिससे आपकी कलाइयां किनारे से लटक जाएं।","अपनी ऊपरी भुजाओं को स्थिर रखते हुए सांस छोड़ें और डम्बल को अपने कंधों की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0366', 'Dumbbell Over Bench One Arm Neutral Wrist Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up.","Keep your upper arm stationary and curl the dumbbell towards your shoulder, keeping your wrist in a neutral position.","Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["एक हाथ में डम्बल लेकर एक बेंच पर बैठें और अपना हाथ बेंच के ऊपर फैला हुआ रखें, हथेली ऊपर की ओर।","अपनी ऊपरी बांह को स्थिर रखें और अपनी कलाई को तटस्थ स्थिति में रखते हुए डंबल को अपने कंधे की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1441', 'Dumbbell Over Bench One Arm Reverse Wrist Curl', 'lower arms', 'forearms', '["biceps","brachialis"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Rest your forearm on the bench with your wrist hanging off the edge.","Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और एक हाथ में डम्बल पकड़ें, हथेली नीचे की ओर हो।","अपनी कलाई को किनारे से लटकाते हुए अपनी बांह को बेंच पर टिकाएं।","धीरे-धीरे अपनी कलाई को ऊपर की ओर मोड़ें, डम्बल को अपनी बांह की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0367', 'Dumbbell Over Bench One Arm Wrist Curl', 'lower arms', 'forearms', '["biceps","shoulders"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing down.","Rest your forearm on the bench with your wrist hanging off the edge.","Slowly curl your wrist upwards, bringing the dumbbell towards your forearm.","Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.","Repeat for the desired number of repetitions, then switch to the other arm."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और एक हाथ में डम्बल पकड़ें, हथेली नीचे की ओर हो।","अपनी कलाई को किनारे से लटकाते हुए अपनी बांह को बेंच पर टिकाएं।","धीरे-धीरे अपनी कलाई को ऊपर की ओर मोड़ें, डम्बल को अपनी बांह की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर दूसरे हाथ पर स्विच करें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0368', 'Dumbbell Over Bench Revers Wrist Curl', 'lower arms', 'forearms', '["biceps","brachialis"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing down.","Rest your forearms on the bench, allowing your wrists to hang off the edge.","Slowly curl your wrists upward, bringing the dumbbells towards your body.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके एक बेंच पर बैठें और दोनों हाथों में एक-एक डम्बल पकड़ें, हथेलियाँ नीचे की ओर हों।","अपनी बांहों को बेंच पर टिकाएं, जिससे आपकी कलाइयां किनारे से लटक जाएं।","धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, डम्बल को अपने शरीर की ओर लाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0369', 'Dumbbell Over Bench Wrist Curl', 'lower arms', 'forearms', '["biceps","brachialis"]', 'dumbbell', 'strength', NULL, '["Sit on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand.","Allow your wrists to hang over the edge of the bench.","Slowly curl your wrists upward, squeezing your forearms at the top of the movement.","Pause for a moment, then slowly lower your wrists back down to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर बैठें, अपने अग्रबाहुओं को बेंच पर टिकाएं और अपनी हथेलियों को ऊपर की ओर रखें, प्रत्येक हाथ में डम्बल पकड़ें।","अपनी कलाइयों को बेंच के किनारे पर लटकने दें।","धीरे-धीरे अपनी कलाइयों को ऊपर की ओर मोड़ें, अपने अग्रबाहुओं को गति के शीर्ष पर निचोड़ें।","एक पल के लिए रुकें, फिर धीरे-धीरे अपनी कलाइयों को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1329', 'Dumbbell Palm Rotational Bent Over Row', 'back', 'upper back', '["biceps","forearms"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.","Bend forward at the hips, keeping your back straight and your knees slightly bent.","Let your arms hang straight down, palms facing your body.","Engage your core and pull the dumbbells up towards your chest, keeping your elbows close to your body.","As you pull the dumbbells up, rotate your palms so they face away from your body.","Squeeze your shoulder blades together at the top of the movement.","Slowly lower the dumbbells back down to the starting position, rotating your palms back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डंबल को ओवरहैंड पकड़ के साथ पकड़ें।","अपनी पीठ को सीधा रखते हुए और अपने घुटनों को थोड़ा मोड़ते हुए, कूल्हों के बल आगे की ओर झुकें।","अपनी भुजाओं को सीधा नीचे लटका दें, हथेलियाँ आपके शरीर की ओर हों।","अपने कोर को संलग्न करें और अपनी कोहनियों को अपने शरीर के करीब रखते हुए डम्बल को अपनी छाती की ओर खींचें।","जैसे ही आप डम्बल को ऊपर खींचते हैं, अपनी हथेलियों को घुमाएँ ताकि वे आपके शरीर से दूर रहें।","आंदोलन के शीर्ष पर अपने कंधे के ब्लेड को एक साथ निचोड़ें।","अपनी हथेलियों को घुमाते हुए धीरे-धीरे डम्बल को प्रारंभिक स्थिति में वापस लाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
INSERT INTO exercises (id, name, body_part, target, secondary, equipment, category, level, instructions, instructions_hi, images, met, tracking, popular, source, active) VALUES
('og-1623', 'Dumbbell Palms In Incline Bench Press', 'upper arms', 'triceps', '["chest","shoulders"]', 'dumbbell', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your back against the backrest and feet flat on the ground.","Hold a dumbbell in each hand with an overhand grip, palms facing inwards.","Extend your arms straight up above your chest, keeping a slight bend in your elbows.","Lower the dumbbells slowly towards your shoulders, keeping your elbows close to your body.","Pause for a moment at the bottom, then press the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","बेंच पर अपनी पीठ बैकरेस्ट से सटाकर और पैरों को ज़मीन पर सपाट करके बैठें।","प्रत्येक हाथ में एक डम्बल पकड़ें, हथेलियाँ अंदर की ओर हों।","अपनी कोहनियों को हल्का सा मोड़ते हुए, अपनी बाहों को अपनी छाती के ऊपर सीधा फैलाएँ।","अपनी कोहनियों को अपने शरीर के करीब रखते हुए, डम्बल को धीरे-धीरे अपने कंधों की ओर नीचे लाएँ।","नीचे एक क्षण के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में दबाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0370', 'Dumbbell Peacher Hammer Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing your torso.","Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.","This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ आपके धड़ की ओर हों।","अपनी कोहनियों को अपने धड़ के पास रखें और अपने हाथों की हथेलियों को तब तक घुमाएँ जब तक वे आगे की ओर न आ जाएँ।","यह आपकी प्रारंभिक स्थिति होगी.","अब, ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","फिर, सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की अनुशंसित मात्रा के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0371', 'Dumbbell Plyo Squat', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.","Lower your body into a squat position by bending your knees and pushing your hips back.","As you reach the bottom of the squat, explode upward, jumping off the ground.","While in the air, quickly switch the position of your feet, landing with your opposite foot forward.","Immediately lower your body back into a squat position and repeat the jump, switching your feet again.","Continue alternating the position of your feet with each jump for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, दोनों हाथों में एक-एक डंबल पकड़ लें।","अपने घुटनों को मोड़कर और अपने कूल्हों को पीछे धकेलते हुए अपने शरीर को स्क्वाट स्थिति में लाएँ।","जैसे ही आप स्क्वाट के निचले भाग तक पहुँचते हैं, जमीन से कूदते हुए ऊपर की ओर विस्फोट करें।","हवा में रहते हुए, अपने विपरीत पैर को आगे की ओर रखते हुए, जल्दी से अपने पैरों की स्थिति बदलें।","तुरंत अपने शरीर को वापस स्क्वाट स्थिति में ले आएं और अपने पैरों को फिर से बदलते हुए छलांग दोहराएं।","दोहराव की वांछित संख्या के लिए प्रत्येक छलांग के साथ अपने पैरों की स्थिति को बदलते रहें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0372', 'Dumbbell Preacher Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a preacher curl bench with your upper arms resting on the pad and your chest against it.","Hold a dumbbell in each hand with your palms facing up and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी ऊपरी बांहों को पैड पर और अपनी छाती को पैड पर टिकाकर प्रीचर कर्ल बेंच पर बैठें।","अपनी हथेलियों को ऊपर की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1673', 'Dumbbell Preacher Curl Over Exercise Ball', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and your back straight.","Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball.","Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.","Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.","Repeat for the desired number of repetitions, then switch arms."]', '["अपने पैरों को ज़मीन पर सपाट और अपनी पीठ को सीधा रखते हुए एक व्यायाम बॉल पर बैठें।","एक हाथ में डंबल को अंडरहैंड ग्रिप से पकड़ें, अपनी कोहनी को एक्सरसाइज बॉल पर टिकाएं।","अपनी ऊपरी भुजा को स्थिर रखते हुए सांस छोड़ें और डंबल को अपने कंधे की ओर मोड़ें।","शीर्ष पर एक पल के लिए रुकें, फिर सांस लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएं, फिर हथियार बदल लें।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1293', 'Dumbbell Press On Exercise Ball', 'chest', 'pectorals', '["shoulders","triceps"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and dumbbells in each hand, resting on your thighs.","Slowly walk your feet forward, rolling the exercise ball until your lower back is supported on the ball and your knees are at a 90-degree angle.","Raise the dumbbells to shoulder height, palms facing forward.","Press the dumbbells upward until your arms are fully extended.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और प्रत्येक हाथ में डम्बल लेकर, अपनी जाँघों पर आराम करते हुए एक व्यायाम गेंद पर बैठें।","व्यायाम गेंद को घुमाते हुए धीरे-धीरे अपने पैरों को आगे बढ़ाएं जब तक कि आपकी पीठ के निचले हिस्से को गेंद पर सहारा न मिल जाए और आपके घुटने 90 डिग्री के कोण पर न आ जाएं।","डम्बल को कंधे की ऊँचाई तक उठाएँ, हथेलियाँ आगे की ओर हों।","डम्बल को तब तक ऊपर की ओर दबाएँ जब तक आपकी भुजाएँ पूरी तरह विस्तारित न हो जाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0373', 'Dumbbell Pronate-Grip Triceps Extension', 'upper arms', 'triceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Sit on a bench or chair with your back straight and feet flat on the ground.","Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.","Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows.","Pause for a moment, then extend your arms back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपनी पीठ सीधी और पैर ज़मीन पर सपाट करके किसी बेंच या कुर्सी पर बैठें।","दोनों हाथों से डम्बल पकड़ें, हथेलियाँ नीचे की ओर हों और अपनी भुजाओं को सीधा ऊपर की ओर फैलाएँ।","अपनी ऊपरी भुजाओं को अपने सिर के पास और कोहनियों को आगे की ओर रखते हुए, अपनी कोहनियों को मोड़कर धीरे-धीरे अपने सिर के पीछे डम्बल को नीचे लाएँ।","एक पल के लिए रुकें, फिर अपनी भुजाओं को वापस प्रारंभिक स्थिति तक फैलाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0374', 'Dumbbell Prone Incline Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', 'intermediate', '["Adjust the bench to a 45-degree incline.","Lie face down on the bench with your chest and stomach resting against it.","Hold a dumbbell in each hand with your palms facing down and your arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["बेंच को 45 डिग्री के झुकाव पर समायोजित करें।","अपनी छाती और पेट को बेंच पर टिकाकर चेहरे के बल लेट जाएँ।","अपनी हथेलियों को नीचे की ओर रखते हुए और अपनी बाहों को पूरी तरह फैलाकर प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Dumbbell_Prone_Incline_Curl/0.jpg","Dumbbell_Prone_Incline_Curl/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-1674', 'Dumbbell Prone Incline Hammer Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Adjust the bench to a 45-degree incline.","Lie face down on the bench with a dumbbell in each hand, palms facing each other.","Allow your arms to hang straight down towards the floor, keeping your elbows slightly bent.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["बेंच को 45 डिग्री के झुकाव पर समायोजित करें।","प्रत्येक हाथ में डम्बल लेकर, हथेलियाँ एक-दूसरे के सामने रखते हुए, बेंच पर मुँह करके लेट जाएँ।","अपनी कोहनियों को थोड़ा मुड़ा हुआ रखते हुए, अपनी भुजाओं को फर्श की ओर सीधा लटकने दें।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","डम्बल को तब तक उठाना जारी रखें जब तक कि आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डम्बल कंधे के स्तर पर न आ जाएं।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0375', 'Dumbbell Pullover', 'chest', 'pectorals', '["latissimus dorsi","triceps"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with your head at one end and your feet on the floor.","Hold a dumbbell with both hands and extend your arms straight above your chest.","Keeping a slight bend in your elbows, slowly lower the dumbbell behind your head until you feel a stretch in your chest and shoulders.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["एक बेंच पर अपने सिर को एक छोर पर और अपने पैरों को फर्श पर रखकर सीधे लेट जाएं।","दोनों हाथों से डम्बल पकड़ें और अपनी बाहों को सीधे अपनी छाती के ऊपर फैलाएँ।","अपनी कोहनियों को हल्का सा मोड़ते हुए धीरे-धीरे डंबल को अपने सिर के पीछे तब तक नीचे लाएं जब तक आपको अपनी छाती और कंधों में खिंचाव महसूस न हो।","एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1294', 'Dumbbell Pullover Hip Extension On Exercise Ball', 'chest', 'pectorals', '["triceps","shoulders","core"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball with your feet flat on the ground and the dumbbell resting on your thighs.","Slowly walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.","Hold the dumbbell with both hands and extend your arms straight up over your chest, keeping a slight bend in your elbows.","Lower the dumbbell behind your head, keeping your arms straight and maintaining control.","Pause for a moment, then raise the dumbbell back to the starting position.","While keeping your arms extended, lift your hips off the ground, squeezing your glutes and engaging your core.","Lower your hips back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और डम्बल को अपनी जाँघों पर टिकाकर एक व्यायाम बॉल पर बैठें।","धीरे-धीरे अपने पैरों को आगे बढ़ाएं, व्यायाम गेंद को अपनी पीठ के नीचे तब तक घुमाएं जब तक कि आपका सिर, गर्दन और ऊपरी पीठ गेंद पर समर्थित न हो जाए।","दोनों हाथों से डम्बल पकड़ें और अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी बाहों को अपनी छाती के ऊपर सीधा फैलाएँ।","अपनी बाहों को सीधा रखते हुए और नियंत्रण बनाए रखते हुए डम्बल को अपने सिर के पीछे नीचे करें।","एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं।","अपनी बाहों को फैलाए रखते हुए, अपने कूल्हों को ज़मीन से ऊपर उठाएं, अपने ग्लूट्स को निचोड़ें और अपने कोर को संलग्न करें।","अपने कूल्हों को वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1295', 'Dumbbell Pullover On Exercise Ball', 'chest', 'pectorals', '["triceps","latissimus dorsi"]', 'dumbbell', 'strength', NULL, '["Sit on an exercise ball and hold a dumbbell with both hands above your chest, arms extended.","Slowly lower the dumbbell behind your head while keeping your arms straight.","Pause for a moment, then raise the dumbbell back to the starting position.","Repeat for the desired number of repetitions."]', '["एक व्यायाम बॉल पर बैठें और दोनों हाथों को अपनी छाती के ऊपर, बाहें फैलाकर डम्बल पकड़ें।","अपनी भुजाओं को सीधा रखते हुए धीरे-धीरे डम्बल को अपने सिर के पीछे नीचे लाएँ।","एक पल के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में उठाएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1700', 'Dumbbell Push Press', 'shoulders', 'delts', '["triceps","core"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder level.","Bend your knees slightly and dip your body down, then explosively extend your legs and press the dumbbells overhead.","Lock out your arms at the top of the movement, then lower the dumbbells back to shoulder level.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में कंधे के स्तर पर डम्बल पकड़ें।","अपने घुटनों को थोड़ा मोड़ें और अपने शरीर को नीचे झुकाएं, फिर अपने पैरों को तेजी से फैलाएं और डम्बल को ऊपर की ओर दबाएं।","अपनी भुजाओं को गति के शीर्ष पर लॉक कर लें, फिर डम्बल को वापस कंधे के स्तर पर नीचे लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0376', 'Dumbbell Raise', 'shoulders', 'delts', '["traps","rhomboids"]', 'dumbbell', 'strength', 'beginner', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Keep your back straight and engage your core.","Raise your arms out to the sides until they are parallel to the floor, keeping a slight bend in your elbows.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ें, हथेलियां आपके शरीर की ओर हों।","अपनी पीठ सीधी रखें और अपने कोर को संलग्न रखें।","अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी भुजाओं को बगल की ओर तब तक उठाएं जब तक कि वे फर्श के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', '["Dumbbell_Raise/0.jpg","Dumbbell_Raise/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-2292', 'Dumbbell Rear Delt Raise', 'shoulders', 'delts', '["trapezius","rhomboids"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ें, हथेलियां आपके शरीर की ओर हों।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी भुजाओं को बगल की ओर उठाएं, अपनी कोहनियों को थोड़ा मोड़ते हुए, जब तक कि वे फर्श के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0377', 'Dumbbell Rear Delt Row_shoulder', 'shoulders', 'delts', '["trapezius","rhomboids"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and knees slightly bent.","Hold a dumbbell in each hand with your palms facing your body.","Bend forward at the waist, keeping your back straight and your core engaged.","Extend your arms straight down towards the floor, with a slight bend in your elbows.","Raise the dumbbells out to the sides, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर और घुटनों को थोड़ा मोड़कर खड़े हो जाएं।","अपनी हथेलियों को अपने शरीर की ओर रखते हुए प्रत्येक हाथ में एक डम्बल पकड़ें।","अपनी पीठ को सीधा रखते हुए और अपने कोर को व्यस्त रखते हुए, कमर के बल आगे की ओर झुकें।","अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी भुजाओं को फर्श की ओर सीधा फैलाएँ।","अपने कंधे के ब्लेड को एक साथ निचोड़ते हुए, डम्बल को किनारे की ओर उठाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0378', 'Dumbbell Rear Fly', 'shoulders', 'delts', '["trapezius","rhomboids"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight down towards the ground, palms facing each other.","Keeping a slight bend in your elbows, lift your arms out to the sides and squeeze your shoulder blades together.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ लें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी भुजाओं को ज़मीन की ओर सीधा फैलाएँ, हथेलियाँ एक-दूसरे के सामने हों।","अपनी कोहनियों को थोड़ा मोड़ते हुए, अपनी भुजाओं को बगल की ओर उठाएं और अपने कंधे के ब्लेड को एक साथ दबाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0380', 'Dumbbell Rear Lateral Raise', 'shoulders', 'delts', '["traps","rhomboids"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.","Bend your knees slightly and hinge forward at the hips, keeping your back straight and core engaged.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the floor.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई की दूरी पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ें, हथेलियां आपके शरीर की ओर हों।","अपने घुटनों को थोड़ा मोड़ें और कूल्हों पर आगे की ओर झुकें, अपनी पीठ को सीधा रखें और कोर को व्यस्त रखें।","अपनी भुजाओं को बगल की ओर उठाएं, अपनी कोहनियों को थोड़ा मोड़ते हुए, जब तक कि वे फर्श के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0379', 'Dumbbell Rear Lateral Raise (Support Head)', 'shoulders', 'delts', '["traps","rhomboids"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Raise your arms out to the sides, keeping a slight bend in your elbows, until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ लें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी भुजाओं को बगल की ओर उठाएं, अपनी कोहनियों को थोड़ा मोड़ते हुए, जब तक कि वे जमीन के समानांतर न हो जाएं।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0381', 'Dumbbell Rear Lunge', 'upper legs', 'glutes', '["quadriceps","hamstrings","calves"]', 'dumbbell', 'strength', 'intermediate', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.","Take a step backward with your right foot, lowering your body into a lunge position.","Bend your left knee and lower your body until your left thigh is parallel to the ground.","Pause for a moment, then push through your left heel to return to the starting position.","Repeat on the other side, stepping back with your left foot."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं, प्रत्येक हाथ में डम्बल पकड़ें।","अपने दाहिने पैर से एक कदम पीछे ले जाएं, अपने शरीर को नीचे झुकाकर स्थिति में लाएं।","अपने बाएं घुटने को मोड़ें और अपने शरीर को तब तक नीचे करें जब तक कि आपकी बाईं जांघ जमीन के समानांतर न हो जाए।","एक पल के लिए रुकें, फिर प्रारंभिक स्थिति में लौटने के लिए अपनी बायीं एड़ी से धक्का दें।","अपने बाएं पैर से पीछे हटते हुए दूसरी तरफ भी दोहराएं।"]', '["Dumbbell_Rear_Lunge/0.jpg","Dumbbell_Rear_Lunge/1.jpg"]', 5, 'sets', 0, 'opengym', 1),
('og-0382', 'Dumbbell Revers Grip Biceps Curl', 'upper arms', 'biceps', '["forearms"]', 'dumbbell', 'strength', NULL, '["Stand up straight with a dumbbell in each hand, palms facing down and arms fully extended.","Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.","Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.","Hold the contracted position for a brief pause as you squeeze your biceps.","Inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the desired number of repetitions."]', '["प्रत्येक हाथ में डम्बल लेकर सीधे खड़े हो जाएं, हथेलियाँ नीचे की ओर हों और बाहें पूरी तरह फैली हुई हों।","अपनी ऊपरी बांहों को स्थिर रखते हुए, सांस छोड़ें और अपने बाइसेप्स को सिकोड़ते हुए वजन को मोड़ें।","जब तक आपके बाइसेप्स पूरी तरह से सिकुड़ न जाएं और डंबल कंधे के स्तर पर न आ जाएं, तब तक वजन उठाना जारी रखें।","जब आप अपने बाइसेप्स को निचोड़ते हैं तो थोड़ी देर के लिए अनुबंधित स्थिति में रहें।","श्वास लें और धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में लाना शुरू करें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1624', 'Dumbbell Reverse Bench Press', 'chest', 'pectorals', '["triceps","shoulders"]', 'dumbbell', 'strength', NULL, '["Lie flat on a bench with your feet flat on the ground and your knees bent.","Hold a dumbbell in each hand with an overhand grip, palms facing towards your feet.","Extend your arms straight up towards the ceiling, keeping a slight bend in your elbows.","Slowly lower the dumbbells towards your chest, allowing your elbows to flare out to the sides.","Pause for a moment at the bottom, then push the dumbbells back up to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को ज़मीन पर सपाट करके और अपने घुटनों को मोड़कर एक बेंच पर सीधे लेट जाएँ।","प्रत्येक हाथ में एक डम्बल पकड़ें, हथेलियाँ आपके पैरों की ओर हों।","अपनी कोहनियों को हल्का सा मोड़ते हुए अपनी भुजाओं को छत की ओर सीधा फैलाएँ।","धीरे-धीरे डम्बल को अपनी छाती की ओर नीचे लाएँ, जिससे आपकी कोहनियाँ बगल की ओर फैल जाएँ।","नीचे एक क्षण के लिए रुकें, फिर डम्बल को वापस प्रारंभिक स्थिति में धकेलें।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-0383', 'Dumbbell Reverse Fly', 'shoulders', 'delts', '["trapezius","rhomboids"]', 'dumbbell', 'strength', NULL, '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.","Bend your knees slightly and hinge forward at the hips, keeping your back straight.","Extend your arms straight down in front of you, palms facing each other.","Keeping a slight bend in your elbows, raise your arms out to the sides until they are parallel to the ground.","Pause for a moment at the top, then slowly lower your arms back down to the starting position.","Repeat for the desired number of repetitions."]', '["अपने पैरों को कंधे की चौड़ाई पर फैलाकर खड़े हो जाएं और प्रत्येक हाथ में डंबल पकड़ लें।","अपने घुटनों को थोड़ा मोड़ें और अपनी पीठ को सीधा रखते हुए कूल्हों पर आगे की ओर झुकें।","अपनी भुजाओं को अपने सामने सीधा फैलाएँ, हथेलियाँ एक-दूसरे के सामने हों।","अपनी कोहनियों को थोड़ा मोड़ते हुए, अपनी भुजाओं को बगल की ओर तब तक उठाएँ जब तक वे ज़मीन के समानांतर न हो जाएँ।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे अपनी भुजाओं को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1330', 'Dumbbell Reverse Grip Incline Bench One Arm Row', 'back', 'upper back', '["biceps","shoulders"]', 'dumbbell', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Place a dumbbell on the floor next to the bench.","Stand facing the bench with your feet shoulder-width apart.","Bend at the waist and place your left knee and left hand on the bench for support.","Pick up the dumbbell with your right hand using a reverse grip (palm facing down).","Keep your back straight and your core engaged.","Pull the dumbbell up towards your chest, keeping your elbow close to your body.","Squeeze your back muscles at the top of the movement.","Lower the dumbbell back down to the starting position in a controlled manner.","Repeat for the desired number of repetitions.","Switch sides and repeat the exercise with your left arm."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","बेंच के बगल में फर्श पर डम्बल रखें।","अपने पैरों को कंधे की चौड़ाई से अलग रखते हुए बेंच की ओर मुंह करके खड़े हो जाएं।","कमर को मोड़ें और अपने बाएँ घुटने और बाएँ हाथ को सहारे के लिए बेंच पर रखें।","रिवर्स ग्रिप (हथेली नीचे की ओर) का उपयोग करके अपने दाहिने हाथ से डम्बल उठाएं।","अपनी पीठ सीधी रखें और अपने कोर को व्यस्त रखें।","अपनी कोहनी को अपने शरीर के पास रखते हुए डम्बल को अपनी छाती की ओर ऊपर खींचें।","आंदोलन के शीर्ष पर अपनी पीठ की मांसपेशियों को निचोड़ें।","डम्बल को नियंत्रित तरीके से वापस प्रारंभिक स्थिति में लाएँ।","दोहराव की वांछित संख्या के लिए दोहराएँ।","करवट बदलें और अपने बाएं हाथ से व्यायाम दोहराएं।"]', NULL, 5, 'sets', 0, 'opengym', 1),
('og-1331', 'Dumbbell Reverse Grip Incline Bench Two Arm Row', 'back', 'upper back', '["biceps","forearms"]', 'dumbbell', 'strength', NULL, '["Set up an incline bench at a 45-degree angle.","Sit on the bench with your chest against the backrest and your feet flat on the ground.","Hold a dumbbell in each hand with an underhand grip.","Lean forward and let your arms hang straight down, fully extended.","Pull the dumbbells up towards your chest, squeezing your shoulder blades together.","Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.","Repeat for the desired number of repetitions."]', '["45 डिग्री के कोण पर एक झुकी हुई बेंच स्थापित करें।","बेंच पर अपनी छाती को बैकरेस्ट से सटाकर बैठें और आपके पैर ज़मीन पर सपाट हों।","प्रत्येक हाथ में एक डम्बल को अंडरहैंड ग्रिप से पकड़ें।","आगे की ओर झुकें और अपनी भुजाओं को पूरी तरह फैलाकर सीधा नीचे लटका दें।","अपने कंधे के ब्लेड को एक साथ दबाते हुए, डम्बल को अपनी छाती की ओर खींचें।","शीर्ष पर एक पल के लिए रुकें, फिर धीरे-धीरे डम्बल को वापस प्रारंभिक स्थिति में ले आएं।","दोहराव की वांछित संख्या के लिए दोहराएँ।"]', NULL, 5, 'sets', 0, 'opengym', 1)
